{"command":"cat > /tmp/pngdec.py << 'PY'
import zlib, struct
def decode(path):
    d=open(path,'rb').read()
    pos=8; w=h=None; bit=None; color=None; data=b''
    while pos < len(d):
        ln, typ = struct.unpack(">I4s", d[pos:pos+8]); chunk=d[pos+8:pos+8+ln]; pos+=12+ln
        if typ==b'IHDR':
            w,h,bit,color,comp,filt,inter = struct.unpack(">IIBBBBB", chunk)
        elif typ==b'IDAT':
            data+=chunk
        elif typ==b'IEND':
            break
    raw=zlib.decompress(data)
    # color 6 = RGBA, 2=RGB, etc
    bpp={6:4,2:3,0:1,4:2}[color]
    stride=w*bpp
    out=bytearray(w*h*bpp)
    prev=bytearray(stride)
    p=0
    for y in range(h):
        filt=raw[p]; p+=1
        line=bytearray(raw[p:p+stride]); p+=stride
        if filt==1:
            for i in range(bpp,stride): line[i]=(line[i]+line[i-bpp])&255
        elif filt==2:
            for i in range(stride): line[i]=(line[i]+prev[i])&255
        elif filt==3:
            for i in range(stride):
                a=line[i-bpp] if i>=bpp else 0
                line[i]=(line[i]+((a+prev[i])>>1))&255
        elif filt==4:
            for i in range(stride):
                a=line[i-bpp] if i>=bpp else 0; b=prev[i]; c=prev[i-bpp] if i>=bpp else 0
                pp=a+b-c; pa=abs(pp-a); pb=abs(pp-b); pc=abs(pp-c)
                pr=a if (pa<=pb and pa<=pc) else (b if pb<=pc else c)
                line[i]=(line[i]+pr)&255
        out[y*stride:(y+1)*stride]=line
        prev=line
    return w,h,bpp,out

def pixel(w,h,bpp,out,x,y):
    i=(y*w+x)*bpp
    return tuple(out[i:i+bpp])
