import sys; sys.path.insert(0,'/tmp')
from pngdec import decode, pixel
import subprocess, os
EXE="/workspace/executable"
def gen(args, out="/tmp/t/probe.png"):
    if os.path.exists(out): os.remove(out)
    subprocess.run([EXE]+args+["-o",out], capture_output=True, cwd="/tmp/t")
    return decode(out)

def bbox(w,h,bpp,out, color=(40,42,54)):
    minx=miny=10**9; maxx=maxy=-1
    for y in range(h):
        for x in range(w):
            if pixel(w,h,bpp,out,x,y)[:3]==color:
                minx=min(minx,x); maxx=max(maxx,x); miny=min(miny,y); maxy=max(maxy,y)
    return minx,maxx,miny,maxy

for my in [0,10,40,80,81,82,90,100]:
    w,h,bpp,out=gen(["-c","hello","--scale-factor","1","--margin-x","20","--margin-y",str(my)])
