from pngdec import decode, pixel
import subprocess, os, collections
EXE="/workspace/executable"
def gen(args):
    out="/tmp/t/probe.png"
    if os.path.exists(out): os.remove(out)
    subprocess.run([EXE]+args+["-o",out], capture_output=True, cwd="/tmp/t")
    return decode(out)
def rows(label,args):
    w,h,bpp,out=gen(["--scale-factor","1","--margin-x","0","--margin-y","0"]+args)
    print(label,w,h)
    cur=None
    for y in range(35,h-10):
        xs=[x for x in range(10,340) if pixel(w,h,bpp,out,x,y)[:3]!=(40,42,54)]
        if xs:
            if cur is None: cur=[y,y,min(xs),max(xs), collections.Counter(pixel(w,h,bpp,out,x,y)[:3] for x in xs).most_common(1)[0][0]]
            else: cur[1]=y; cur[2]=min(cur[2],min(xs)); cur[3]=max(cur[3],max(xs))
        else:
            if cur: print(" ",cur); cur=None
    if cur: print(" ",cur)
rows("stdout only",["-e","echo out_only_stdout"])
rows("stderr only",["-e","echo err_only_stderr >&2"])
rows("both",["-e","echo outA; echo errB >&2"])
rows("skip",["-e","echo hi","--skip"])
rows("exit code fail",["-e","exit 3"])
rows("cd /tmp then pwd?",["-e","pwd"])
