// TrueType font loading and glyph rasterisation (original implementation).
use std::collections::HashMap;
use std::sync::OnceLock;

#[derive(Clone, Debug)]
struct GlyphOutline {
    contours: Vec<Vec<(f32, f32)>>, // flattened polygons in font units
    advance: f32,
}

#[derive(Clone, Debug)]
pub struct Font {
    units_per_em: f32,
    glyphs: Vec<GlyphOutline>,
    cmap: HashMap<u32, u16>,
    ascender: f32,
}

fn u16b(d: &[u8], o: usize) -> u16 { u16::from_be_bytes([d[o], d[o+1]]) }
fn i16b(d: &[u8], o: usize) -> i16 { i16::from_be_bytes([d[o], d[o+1]]) }
fn u32b(d: &[u8], o: usize) -> u32 { u32::from_be_bytes([d[o], d[o+1], d[o+2], d[o+3]]) }

impl Font {
    pub fn load_path(path: &str) -> Option<Font> {
        let data = std::fs::read(path).ok()?;
        Self::parse(&data)
    }
    pub fn parse(data: &[u8]) -> Option<Font> {
        if data.len() < 12 { return None; }
        let num_tables = u16b(data, 4) as usize;
        let mut tables: HashMap<String, (usize, usize)> = HashMap::new();
        for i in 0..num_tables {
            let off = 12 + i * 16;
            if off + 16 > data.len() { break; }
            let tag = std::str::from_utf8(&data[off..off+4]).ok()?.to_string();
            let toff = u32b(data, off+8) as usize;
            let tlen = u32b(data, off+12) as usize;
            tables.insert(tag, (toff, tlen));
        }
        let (head_off, _) = *tables.get("head")?;
        let units_per_em = u16b(data, head_off + 18) as f32;
        let index_to_loc = i16b(data, head_off + 50);
        let (maxp_off, _) = *tables.get("maxp")?;
        let num_glyphs = u16b(data, maxp_off + 4) as usize;
        let (hhea_off, _) = *tables.get("hhea")?;
        let ascender = i16b(data, hhea_off + 4) as f32;
        let num_h = u16b(data, hhea_off + 34) as usize;
        let (hmtx_off, _) = *tables.get("hmtx")?;
        let mut advances: Vec<f32> = Vec::with_capacity(num_glyphs);
        for g in 0..num_glyphs {
            if g < num_h {
                advances.push(u16b(data, hmtx_off + g*4) as f32);
            } else {
                advances.push(*advances.last().unwrap_or(&0.0));
            }
        }
        // loca
        let (loca_off, _) = *tables.get("loca")?;
        let mut loca: Vec<usize> = Vec::with_capacity(num_glyphs + 1);
        if index_to_loc == 1 {
            for i in 0..=num_glyphs { loca.push(u32b(data, loca_off + i*4) as usize); }
        } else {
            for i in 0..=num_glyphs { loca.push(u16b(data, loca_off + i*2) as usize * 2); }
        }
        let (glyf_off, _) = *tables.get("glyf")?;
        // cmap
        let cmap = parse_cmap(data, &tables)?;
        let mut glyphs = Vec::with_capacity(num_glyphs);
        for g in 0..num_glyphs {
            let start = glyf_off + loca[g];
            let end = glyf_off + loca[g+1];
            let adv = *advances.get(g).unwrap_or(&0.0);
            let outline = if start < end && end <= data.len() {
                parse_glyph(data, start, end, glyf_off, &loca, adv, 0)
            } else { GlyphOutline { contours: Vec::new(), advance: adv } };
            glyphs.push(outline);
        }
        Some(Font { units_per_em, glyphs, cmap, ascender })
    }
    pub fn ascender(&self) -> f32 { self.ascender }
    fn glyph_index(&self, ch: char) -> u16 {
        *self.cmap.get(&(ch as u32)).unwrap_or(&0)
    }
    pub fn advance(&self, ch: char, size: f32) -> f32 {
        let gi = self.glyph_index(ch) as usize;
        if let Some(g) = self.glyphs.get(gi) {
            g.advance * size / self.units_per_em
        } else { size * 0.6 }
    }
    pub fn text_width(&self, text: &str, size: f32) -> f32 {
        text.chars().map(|c| self.advance(c, size)).sum()
    }
    // Rasterise a glyph. Returns (width, height, left_bearing_px, top_from_baseline_px, alpha bytes)
    pub fn raster(&self, ch: char, size: f32) -> (u32, u32, i32, i32, Vec<u8>) {
        let gi = self.glyph_index(ch) as usize;
        let glyph = match self.glyphs.get(gi) { Some(g) => g, None => return (0,0,0,0,Vec::new()) };
        if glyph.contours.is_empty() { return (0,0,0,0,Vec::new()); }
        let scale = size / self.units_per_em;
        // bounding box
        let mut minx = f32::INFINITY; let mut miny = f32::INFINITY;
        let mut maxx = f32::NEG_INFINITY; let mut maxy = f32::NEG_INFINITY;
        for c in &glyph.contours { for &(x,y) in c { minx=minx.min(x); maxx=maxx.max(x); miny=miny.min(y); maxy=maxy.max(y); } }
        if !minx.is_finite() { return (0,0,0,0,Vec::new()); }
        // glyph y is up-positive; pixel y = baseline - y*scale
        let left = (minx * scale).floor() as i32;
        let right = (maxx * scale).ceil() as i32;
        let top_up = (maxy * scale).ceil() as i32; // px above baseline
        let bottom_up = (miny * scale).floor() as i32; // px above baseline (negative if descends)
        let w = (right - left).max(0) as u32;
        let h = (top_up - bottom_up).max(0) as u32;
        if w == 0 || h == 0 { return (0,0,0,0,Vec::new()); }
        let ss: i32 = 4;
        let mut alpha = vec![0u8; (w*h) as usize];
        // Transform contours to supersampled pixel coords: sx = (x*scale - left)*ss, sy = (top_up - y*scale)*ss
        let polys: Vec<Vec<(f32,f32)>> = glyph.contours.iter().map(|c| {
            c.iter().map(|&(x,y)| ((x*scale - left as f32) * ss as f32, (top_up as f32 - y*scale) * ss as f32)).collect::<Vec<_>>()
        }).collect();
        let ssw = w as i32 * ss; let ssh = h as i32 * ss;
        for sy in 0..ssh {
            for sx in 0..ssw {
                let px = sx as f32 + 0.5; let py = sy as f32 + 0.5;
                if point_inside(&polys, px, py) {
                    let idx = ((sy/ss) as u32 * w + (sx/ss) as u32) as usize;
                    // accumulate coverage
                    let cur = alpha[idx] as u32;
                    let add = 255 / (ss*ss) as u32;
                    alpha[idx] = (cur + add).min(255) as u8;
                }
            }
        }
        // Fix rounding: recompute per-pixel coverage accurately for full pixels is fine.
        (w, h, left, top_up, alpha)
    }
}

fn point_inside(polys: &[Vec<(f32,f32)>], x: f32, y: f32) -> bool {
    let mut winding: i32 = 0;
    for poly in polys {
        if poly.len() < 2 { continue; }
        for i in 0..poly.len() {
            let (x1,y1) = poly[i];
            let (x2,y2) = poly[(i+1)%poly.len()];
            if y1 <= y {
                if y2 > y && is_left((x1,y1),(x2,y2),(x,y)) > 0.0 { winding += 1; }
            } else {
                if y2 <= y && is_left((x1,y1),(x2,y2),(x,y)) < 0.0 { winding -= 1; }
            }
        }
    }
    winding != 0
}
fn is_left(a:(f32,f32), b:(f32,f32), p:(f32,f32)) -> f32 { (b.0-a.0)*(p.1-a.1) - (p.0-a.0)*(b.1-a.1) }

fn parse_cmap(data: &[u8], tables: &HashMap<String,(usize,usize)>) -> Option<HashMap<u32,u16>> {
    let (off, _) = *tables.get("cmap")?;
    let num = u16b(data, off+2) as usize;
    let mut chosen: Option<usize> = None;
    let mut fallback: Option<usize> = None;
    for i in 0..num {
        let rec = off + 4 + i*8;
        let platform = u16b(data, rec);
        let encoding = u16b(data, rec+2);
        let sub_off = off + u32b(data, rec+4) as usize;
        if fallback.is_none() { fallback = Some(sub_off); }
        if (platform == 3 && (encoding == 1 || encoding == 10)) || platform == 0 { chosen = Some(sub_off); break; }
    }
    let sub = chosen.or(fallback)?;
    let format = u16b(data, sub);
    let mut map = HashMap::new();
    match format {
        4 => {
            let seg_count = (u16b(data, sub+6) / 2) as usize;
            let end_off = sub + 14;
            let start_off = end_off + 2*seg_count + 2;
            let delta_off = start_off + 2*seg_count;
            let range_off = delta_off + 2*seg_count;
            for s in 0..seg_count {
                let end_c = u16b(data, end_off + s*2) as u32;
                let start_c = u16b(data, start_off + s*2) as u32;
                let delta = i16b(data, delta_off + s*2) as i32;
                let ro = u16b(data, range_off + s*2) as usize;
                for c in start_c..=end_c.min(0xFFFF) {
                    if c == 0xFFFF { continue; }
                    let gid = if ro == 0 {
                        ((c as i32 + delta) & 0xFFFF) as u16
                    } else {
                        let idx_pos = range_off + s*2 + ro + (c - start_c) as usize * 2;
                        let g = u16b(data, idx_pos);
                        if g == 0 { 0 } else { ((g as i32 + delta) & 0xFFFF) as u16 }
                    };
                    if gid != 0 { map.insert(c, gid); }
                }
            }
        }
        12 => {
            let n = u32b(data, sub+12) as usize;
            for i in 0..n {
                let rec = sub + 16 + i*12;
                let start_c = u32b(data, rec); let end_c = u32b(data, rec+4); let start_g = u32b(data, rec+8);
                for (k,c) in (start_c..=end_c).enumerate() {
                    map.insert(c, (start_g + k as u32) as u16);
                }
            }
        }
        6 => {
            let first = u16b(data, sub+6) as u32;
            let count = u16b(data, sub+8) as usize;
            for i in 0..count { map.insert(first + i as u32, u16b(data, sub+10+i*2)); }
        }
        _ => {}
    }
    Some(map)
}

fn parse_glyph(data: &[u8], start: usize, end: usize, glyf_off: usize, loca: &[usize], advance: f32, depth: u32) -> GlyphOutline {
    if end - start < 10 || depth > 4 { return GlyphOutline { contours: Vec::new(), advance }; }
    let num_contours = i16b(data, start);
    if num_contours < 0 {
        // composite
        let mut contours = Vec::new();
        let mut pos = start + 10;
        loop {
            if pos + 4 > end { break; }
            let flags = u16b(data, pos); let comp_gid = u16b(data, pos+2) as usize; pos += 4;
            let (dx, dy, args_are_words) = if flags & 0x0001 != 0 {
                if pos + 4 > end { break; }
                let a1 = i16b(data, pos) as f32; let a2 = i16b(data, pos+2) as f32; pos += 4; (a1, a2, true)
            } else {
                if pos + 2 > end { break; }
                let a1 = data[pos] as i8 as f32; let a2 = data[pos+1] as i8 as f32; pos += 2; (a1, a2, false)
            };
            let _ = args_are_words;
            // scale
            let mut sx = 1.0f32; let mut sy = 1.0f32;
            if flags & 0x0008 != 0 { if pos+2<=end { sx = f2dot14(data,pos); sy = sx; pos+=2; } }
            else if flags & 0x0040 != 0 { if pos+4<=end { sx = f2dot14(data,pos); sy = f2dot14(data,pos+2); pos+=4; } }
            else if flags & 0x0080 != 0 { if pos+8<=end { pos+=8; } }
            if comp_gid < loca.len()-1 {
                let cs = glyf_off + loca[comp_gid]; let ce = glyf_off + loca[comp_gid+1];
                if cs < ce && ce <= data.len() {
                    let sub = parse_glyph(data, cs, ce, glyf_off, loca, advance, depth+1);
                    for contour in sub.contours {
                        contours.push(contour.iter().map(|&(x,y)| (x*sx + dx, y*sy + dy)).collect());
                    }
                }
            }
            if flags & 0x0020 == 0 { break; }
        }
        GlyphOutline { contours, advance }
    } else {
        let nc = num_contours as usize;
        let mut pos = start + 10;
        let mut end_pts = Vec::new();
        for i in 0..nc { end_pts.push(u16b(data, pos + i*2) as usize); }
        pos += nc * 2;
        // skip instructions
        if pos + 2 > end { return GlyphOutline { contours: Vec::new(), advance }; }
        let instr_len = u16b(data, pos) as usize; pos += 2 + instr_len;
        let total_pts = end_pts.last().copied().unwrap_or(0) + 1;
        if total_pts == 0 { return GlyphOutline { contours: Vec::new(), advance }; }
        let mut flags_vec: Vec<u8> = Vec::with_capacity(total_pts);
        while flags_vec.len() < total_pts && pos < end {
            let f = data[pos]; pos += 1; flags_vec.push(f);
            if f & 0x08 != 0 {
                if pos >= end { break; }
                let rep = data[pos]; pos += 1;
                for _ in 0..rep { flags_vec.push(f); }
            }
        }
        flags_vec.truncate(total_pts);
        let mut xs: Vec<f32> = Vec::with_capacity(total_pts);
        let mut x = 0i32;
        for &f in &flags_vec {
            if f & 0x02 != 0 {
                if pos >= end { break; }
                let v = data[pos] as i32; pos += 1;
                x += if f & 0x10 != 0 { v } else { -v };
            } else if f & 0x10 == 0 {
                if pos + 1 >= end { break; }
                x += i16b(data, pos) as i32; pos += 2;
            }
            xs.push(x as f32);
        }
        let mut ys: Vec<f32> = Vec::with_capacity(total_pts);
        let mut y = 0i32;
        for &f in &flags_vec {
            if f & 0x04 != 0 {
                if pos >= end { break; }
                let v = data[pos] as i32; pos += 1;
                y += if f & 0x20 != 0 { v } else { -v };
            } else if f & 0x20 == 0 {
                if pos + 1 >= end { break; }
                y += i16b(data, pos) as i32; pos += 2;
            }
            ys.push(y as f32);
        }
        let pts: Vec<(f32,f32,bool)> = (0..flags_vec.len()).map(|i| (xs.get(i).copied().unwrap_or(0.0), ys.get(i).copied().unwrap_or(0.0), flags_vec[i] & 0x01 != 0)).collect();
        // build contours with quadratic flattening
        let mut contours = Vec::new();
        let mut start_idx = 0usize;
        for &end_idx in &end_pts {
            if end_idx >= pts.len() { break; }
            let contour_pts = &pts[start_idx..=end_idx];
            let flat = flatten_contour(contour_pts);
            if flat.len() >= 2 { contours.push(flat); }
            start_idx = end_idx + 1;
        }
        GlyphOutline { contours, advance }
    }
}
fn f2dot14(d: &[u8], o: usize) -> f32 { i16b(d,o) as f32 / 16384.0 }

fn flatten_contour(pts: &[(f32,f32,bool)]) -> Vec<(f32,f32)> {
    if pts.is_empty() { return Vec::new(); }
    // Build sequence starting with an on-curve point
    let mut seq: Vec<(f32,f32,bool)> = pts.to_vec();
    if !seq[0].2 {
        let last = *seq.last().unwrap();
        if last.2 { seq.insert(0, last); seq.pop(); }
        else {
            let mid = ((seq[0].0+last.0)/2.0, (seq[0].1+last.1)/2.0, true);
            seq.insert(0, mid);
        }
    }
    let mut out: Vec<(f32,f32)> = Vec::new();
    out.push((seq[0].0, seq[0].1));
    let n = seq.len();
    let mut i = 1usize;
    while i <= n {
        let cur = seq[i % n];
        if cur.2 {
            out.push((cur.0, cur.1));
            i += 1;
        } else {
            let ctrl = cur;
            let next = seq[(i+1) % n];
            let endp = if next.2 { (next.0, next.1) } else { ((ctrl.0+next.0)/2.0, (ctrl.1+next.1)/2.0) };
            let startp = *out.last().unwrap();
            let steps = 10;
            for s in 1..=steps {
                let t = s as f32 / steps as f32;
                let mt = 1.0 - t;
                let px = mt*mt*startp.0 + 2.0*mt*t*ctrl.0 + t*t*endp.0;
                let py = mt*mt*startp.1 + 2.0*mt*t*ctrl.1 + t*t*endp.1;
                out.push((px,py));
            }
            i += if next.2 { 2 } else { 1 };
            if i > n + 1 { break; }
        }
        if i > n { break; }
    }
    out
}

pub struct FontSet {
    pub mono: Font,
    pub sans: Font,
    pub serif: Font,
    pub mono_bold: Font,
    pub sans_bold: Font,
}

static FONTS: OnceLock<Option<FontSet>> = OnceLock::new();

pub fn fonts() -> Option<&'static FontSet> {
    FONTS.get_or_init(|| {
        let base = "/usr/share/fonts/truetype/dejavu";
        let mono = Font::load_path(&format!("{}/DejaVuSansMono.ttf", base))?;
        let sans = Font::load_path(&format!("{}/DejaVuSans.ttf", base))?;
        let serif = Font::load_path(&format!("{}/DejaVuSerif.ttf", base)).unwrap_or_else(|| sans.clone());
        let mono_bold = Font::load_path(&format!("{}/DejaVuSansMono-Bold.ttf", base)).unwrap_or_else(|| mono.clone());
        let sans_bold = Font::load_path(&format!("{}/DejaVuSans-Bold.ttf", base)).unwrap_or_else(|| sans.clone());
        Some(FontSet { mono, sans, serif, mono_bold, sans_bold })
    }).as_ref()
}

#[derive(PartialEq, Clone, Copy, Debug)]
pub enum FontKind { Mono, Sans, Serif }

pub fn pick_font(family: &str, kind_hint: FontKind) -> (FontKind, bool) {
    // returns (kind, bold)
    let f = family.trim().to_lowercase();
    if f.contains("dejavu serif") || f == "dejavu serif" {
        return (FontKind::Serif, false);
    }
    if f.contains("dejavu sans mono") {
        return (FontKind::Mono, false);
    }
    if f.contains("dejavu sans") {
        return (FontKind::Sans, false);
    }
    if f.contains("caskaydia") || f.contains("cascadia") || f.contains("nerd font") {
        return (FontKind::Mono, false);
    }
    if f.contains("pacifico") {
        return (FontKind::Serif, false);
    }
    match kind_hint {
        FontKind::Mono => {
            // Unknown code font falls back to Sans in the original (generic fallback).
            // But the configured default is handled above. For other unknown names use Sans.
            if f.is_empty() { (FontKind::Sans, false) } else { (FontKind::Sans, false) }
        }
        k => (k, false),
    }
}

pub fn get_font(family: &str, hint: FontKind) -> Option<(&'static Font, FontKind)> {
    let set = fonts()?;
    let (kind, _bold) = pick_font(family, hint);
    let font = match kind {
        FontKind::Mono => &set.mono,
        FontKind::Sans => &set.sans,
        FontKind::Serif => &set.serif,
    };
    Some((font, kind))
}

// Glyph cache keyed by (font ptr-ish kind, char, size quantized)
pub struct TextRenderer {
    cache: HashMap<(u8, char, u32), (u32,u32,i32,i32,Vec<u8>)>,
}
impl TextRenderer {
    pub fn new() -> Self { Self { cache: HashMap::new() } }
    pub fn width(&mut self, kind: FontKind, family: &str, text: &str, size: f32) -> f32 {
        if let Some((font, _)) = get_font(family, kind) {
            font.text_width(text, size)
        } else {
            text.chars().count() as f32 * size * 0.6
        }
    }
    pub fn draw(
        &mut self,
        img: &mut crate::image::Image,
        kind: FontKind,
        family: &str,
        text: &str, x: f32, baseline: f32, size: f32,
        color: (u8,u8,u8,u8),
    ) {
        let font = match get_font(family, kind) { Some((f,_)) => f, None => return };
        let mut cx = x;
        let kind_id = match kind { FontKind::Mono => 0u8, FontKind::Sans => 1, FontKind::Serif => 2 };
        // specific font selected by family may differ from hint kind; recompute effective kind
        let (_, eff_kind) = pick_font(family, kind);
        let eff_id = match eff_kind { FontKind::Mono => 0u8, FontKind::Sans => 1, FontKind::Serif => 2 };
        let _ = kind_id;
        for ch in text.chars() {
            let adv = font.advance(ch, size);
            if ch != ' ' && ch != '\t' {
                let key = (eff_id, ch, size.to_bits());
                let entry = self.cache.entry(key).or_insert_with(|| font.raster(ch, size));
                let (w,h,left,top_up,alpha) = entry.clone();
                if w > 0 {
                    let dx = (cx + left as f32).round() as i32;
                    let dy = (baseline - top_up as f32).round() as i32;
                    img.draw_alpha(dx, dy, w, h, &alpha, color);
                }
            }
            cx += adv;
        }
    }
}
RUST
