// RGBA image buffer, drawing primitives, PNG encode/decode.
use std::fmt;

#[derive(Clone)]
pub struct Image {
    pub width: u32,
    pub height: u32,
    pub data: Vec<u8>, // RGBA
}

#[derive(Debug, Clone)]
pub struct PngError(pub String);
impl fmt::Display for PngError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result { write!(f, "{}", self.0) }
}
impl std::error::Error for PngError {}

pub type Color = (u8, u8, u8, u8);

pub fn blend_over(dst: &mut [u8], src: Color) {
    let sa = src.3 as f32 / 255.0;
    if sa <= 0.0 { return; }
    if sa >= 1.0 {
        dst[0] = src.0; dst[1] = src.1; dst[2] = src.2; dst[3] = 255; return;
    }
    let da = dst[3] as f32 / 255.0;
    let out_a = sa + da * (1.0 - sa);
    if out_a <= 0.0 { dst[0]=0; dst[1]=0; dst[2]=0; dst[3]=0; return; }
    for i in 0..3 {
        let s = [src.0, src.1, src.2][i] as f32;
        let d = dst[i] as f32;
        dst[i] = ((s * sa + d * da * (1.0 - sa)) / out_a).round().clamp(0.0,255.0) as u8;
    }
    dst[3] = (out_a * 255.0).round().clamp(0.0,255.0) as u8;
}

// Parse a hex colour; panics are emulated by the caller (see color parsing helper in main)
pub fn hex_to_rgba(s: &str) -> Option<Color> {
    // assumes validated format #RRGGBB or #RRGGBBAA
    if !s.starts_with('#') { return None; }
    let h = &s[1..];
    let parse = |i: usize| u8::from_str_radix(&h[i..i+2], 16).ok();
    match h.len() {
        6 => Some((parse(0)?, parse(2)?, parse(4)?, 255)),
        8 => Some((parse(0)?, parse(2)?, parse(4)?, parse(6)?)),
        _ => None,
    }
}

impl Image {
    pub fn new(width: u32, height: u32) -> Option<Image> {
        if width == 0 || height == 0 { return None; }
        let len = (width as usize).checked_mul(height as usize)?.checked_mul(4)?;
        Some(Image { width, height, data: vec![0; len] })
    }
    pub fn pixel(&self, x: u32, y: u32) -> Color {
        if x >= self.width || y >= self.height { return (0,0,0,0); }
        let i = ((y*self.width + x)*4) as usize;
        (self.data[i], self.data[i+1], self.data[i+2], self.data[i+3])
    }
    pub fn set_blend(&mut self, x: i32, y: i32, color: Color) {
        if x < 0 || y < 0 || x >= self.width as i32 || y >= self.height as i32 { return; }
        let i = ((y as u32 * self.width + x as u32)*4) as usize;
        blend_over(&mut self.data[i..i+4], color);
    }
    pub fn fill_rect(&mut self, x: f32, y: f32, w: f32, h: f32, color: Color) {
        let x0 = x.round() as i32; let y0 = y.round() as i32;
        let x1 = (x + w).round() as i32; let y1 = (y + h).round() as i32;
        for yy in y0..y1 { for xx in x0..x1 { self.set_blend(xx, yy, color); } }
    }
    pub fn fill_rounded_rect(&mut self, x: f32, y: f32, w: f32, h: f32, radius: f32, color: Color) {
        let x0 = x.floor() as i32 - 1; let y0 = y.floor() as i32 - 1;
        let x1 = (x + w).ceil() as i32 + 1; let y1 = (y + h).ceil() as i32 + 1;
        let r = radius.min(w/2.0).min(h/2.0).max(0.0);
        for yy in y0..y1 {
            for xx in x0..x1 {
                let coverage = rounded_rect_coverage(xx as f32 + 0.5, yy as f32 + 0.5, x, y, w, h, r, 0.0);
                if coverage > 0.0 {
                    let a = (color.3 as f32 * coverage).round().clamp(0.0,255.0) as u8;
                    self.set_blend(xx, yy, (color.0, color.1, color.2, a));
                }
            }
        }
    }
    pub fn stroke_rounded_rect(&mut self, x: f32, y: f32, w: f32, h: f32, radius: f32, line_width: f32, color: Color) {
        let x0 = x.floor() as i32 - 2; let y0 = y.floor() as i32 - 2;
        let x1 = (x + w).ceil() as i32 + 2; let y1 = (y + h).ceil() as i32 + 2;
        let r = radius.min(w/2.0).min(h/2.0).max(0.0);
        for yy in y0..y1 {
            for xx in x0..x1 {
                // coverage outside outer + inside inner hole
                let outer = rounded_rect_coverage(xx as f32+0.5, yy as f32+0.5, x, y, w, h, r, 0.0);
                if outer <= 0.0 { continue; }
                let inner = rounded_rect_coverage(xx as f32+0.5, yy as f32+0.5, x+line_width, y+line_width, w-2.0*line_width, h-2.0*line_width, (r-line_width).max(0.0), 0.0);
                let cov = (outer - inner).clamp(0.0,1.0);
                if cov > 0.0 {
                    let a = (color.3 as f32 * cov).round().clamp(0.0,255.0) as u8;
                    self.set_blend(xx, yy, (color.0,color.1,color.2,a));
                }
            }
        }
    }
    pub fn draw_alpha(&mut self, dx: i32, dy: i32, w: u32, h: u32, alpha: &[u8], color: Color) {
        for yy in 0..h as i32 {
            for xx in 0..w as i32 {
                let a = alpha[(yy as u32 * w + xx as u32) as usize] as f32 / 255.0;
                if a <= 0.0 { continue; }
                let ca = (color.3 as f32 * a).round().clamp(0.0,255.0) as u8;
                self.set_blend(dx + xx, dy + yy, (color.0,color.1,color.2,ca));
            }
        }
    }
    pub fn draw_image_scaled(&mut self, src: &Image, dx: f32, dy: f32, dw: u32, dh: u32) {
        if dw == 0 || dh == 0 { return; }
        let x0 = dx.round() as i32; let y0 = dy.round() as i32;
        for yy in 0..dh as i32 {
            for xx in 0..dw as i32 {
                // bilinear sample
                let fx = (xx as f32 + 0.5) * src.width as f32 / dw as f32 - 0.5;
                let fy = (yy as f32 + 0.5) * src.height as f32 / dh as f32 - 0.5;
                let col = sample_bilinear(src, fx, fy);
                self.set_blend(x0 + xx, y0 + yy, col);
            }
        }
    }
    pub fn to_png(&self) -> Vec<u8> {
        encode_png(self)
    }
}

fn sample_bilinear(src: &Image, fx: f32, fy: f32) -> Color {
    let x0 = fx.floor() as i32; let y0 = fy.floor() as i32;
    let tx = fx - x0 as f32; let ty = fy - y0 as f32;
    let mut out = [0f32;4];
    for (dx, wx) in [(0, 1.0-tx), (1, tx)] {
        for (dy, wy) in [(0, 1.0-ty), (1, ty)] {
            let p = src.pixel((x0+dx).clamp(0, src.width as i32 -1) as u32, (y0+dy).clamp(0, src.height as i32 -1) as u32);
            let wgt = wx*wy;
            out[0] += p.0 as f32 * wgt; out[1] += p.1 as f32 * wgt; out[2] += p.2 as f32 * wgt; out[3] += p.3 as f32 * wgt;
        }
    }
    (out[0].round() as u8, out[1].round() as u8, out[2].round() as u8, out[3].round() as u8)
}

fn rounded_rect_coverage(px: f32, py: f32, x: f32, y: f32, w: f32, h: f32, r: f32, _pad: f32) -> f32 {
    // signed distance to rounded rect (negative inside)
    let cx = x + w/2.0; let cy = y + h/2.0;
    let qx = (px - cx).abs() - (w/2.0 - r);
    let qy = (py - cy).abs() - (h/2.0 - r);
    let ax = qx.max(0.0); let ay = qy.max(0.0);
    let sd = (ax*ax + ay*ay).sqrt() + qx.max(qy).min(0.0) - r;
    (0.5 - sd).clamp(0.0, 1.0)
}

// Gradient / shadow helpers
pub fn interpolate_stops(stops: &[(f32, Color)], t: f32) -> Color {
    if stops.is_empty() { return (0,0,0,0); }
    if stops.len() == 1 { return stops[0].1; }
    let t = t.clamp(0.0, 1.0);
    let mut i = 0;
    while i + 1 < stops.len() && stops[i+1].0 < t { i += 1; }
    if i + 1 >= stops.len() { return stops[stops.len()-1].1; }
    let (p0,c0) = stops[i]; let (p1,c1) = stops[i+1];
    let f = if (p1-p0).abs() < f32::EPSILON { 0.0 } else { (t - p0) / (p1 - p0) };
    let f = f.clamp(0.0,1.0);
    let mix = |a:u8,b:u8| -> u8 { (a as f32 + (b as f32 - a as f32)*f).round().clamp(0.0,255.0) as u8 };
    (mix(c0.0,c1.0), mix(c0.1,c1.1), mix(c0.2,c1.2), mix(c0.3,c1.3))
}

pub fn box_blur_alpha(mask: &mut Vec<f32>, w: usize, h: usize, radius: usize) {
    if radius == 0 || w == 0 || h == 0 { return; }
    // 3 passes approximating gaussian
    for _ in 0..3 {
        // horizontal
        let mut tmp = vec![0f32; w*h];
        for y in 0..h {
            let mut acc = 0f32;
            let r = radius as i32;
            for x in 0..w as i32 {
                let add_idx = (x + r).clamp(0, w as i32 -1) as usize;
                let sub_idx = (x - r - 1).clamp(0, w as i32 -1) as usize;
                // simple sliding window using clamp initialisation is approximate; recompute first
                if x == 0 {
                    acc = 0.0;
                    for k in -r..=r { acc += mask[y*w + (k.clamp(0, w as i32-1)) as usize]; }
                } else {
                    acc += mask[y*w + add_idx] - mask[y*w + sub_idx];
                }
                tmp[y*w + x as usize] = acc / (2*radius+1) as f32;
            }
        }
        *mask = tmp;
        // vertical
        let mut tmp = vec![0f32; w*h];
        for x in 0..w {
            let mut acc = 0f32;
            let r = radius as i32;
            for y in 0..h as i32 {
                if y == 0 {
                    acc = 0.0;
                    for k in -r..=r { acc += mask[(k.clamp(0, h as i32-1)) as usize * w + x]; }
                } else {
                    let add_idx = (y + r).clamp(0, h as i32 -1) as usize;
                    let sub_idx = (y - r - 1).clamp(0, h as i32 -1) as usize;
                    acc += mask[add_idx*w + x] - mask[sub_idx*w + x];
                }
                tmp[y as usize * w + x] = acc / (2*radius+1) as f32;
            }
        }
        *mask = tmp;
    }
}

// ----- PNG encode -----
fn crc32(data: &[u8]) -> u32 {
    let mut crc = 0xFFFFFFFFu32;
    for &b in data {
        crc ^= b as u32;
        for _ in 0..8 {
            crc = if crc & 1 != 0 { (crc >> 1) ^ 0xEDB88320 } else { crc >> 1 };
        }
    }
    !crc
}
fn write_chunk(out: &mut Vec<u8>, name: &[u8;4], data: &[u8]) {
    out.extend_from_slice(&(data.len() as u32).to_be_bytes());
    out.extend_from_slice(name);
    out.extend_from_slice(data);
    let mut crc_data = Vec::with_capacity(4 + data.len());
    crc_data.extend_from_slice(name);
    crc_data.extend_from_slice(data);
    out.extend_from_slice(&crc32(&crc_data).to_be_bytes());
}
pub fn encode_png(img: &Image) -> Vec<u8> {
    let mut out = Vec::new();
    out.extend_from_slice(b"\x89PNG\r\n\x1a\n");
    let mut ihdr = Vec::new();
    ihdr.extend_from_slice(&img.width.to_be_bytes());
    ihdr.extend_from_slice(&img.height.to_be_bytes());
    ihdr.extend_from_slice(&[8, 6, 0, 0, 0]);
    write_chunk(&mut out, b"IHDR", &ihdr);
    // raw scanlines
    let mut raw = Vec::with_capacity((img.width as usize * 4 + 1) * img.height as usize);
    for y in 0..img.height {
        raw.push(0u8);
        let start = (y * img.width * 4) as usize;
        raw.extend_from_slice(&img.data[start..start + (img.width*4) as usize]);
    }
    use std::io::Write;
    let mut enc = flate2::write::ZlibEncoder::new(Vec::new(), flate2::Compression::fast());
    let _ = enc.write_all(&raw);
    let compressed = enc.finish().unwrap_or_default();
    write_chunk(&mut out, b"IDAT", &compressed);
    write_chunk(&mut out, b"IEND", &[]);
    out
}

// ----- PNG decode -----
const PNG_SIG: &[u8;8] = b"\x89PNG\r\n\x1a\n";
pub fn decode_png(data: &[u8]) -> Result<Image, PngError> {
    if data.len() < 8 {
        // Distinguish truncated signature from wrong signature
        if PNG_SIG.starts_with(data) {
            return Err(PngError("Unexpected end of data before image end.".to_string()));
        } else {
            return Err(PngError("Invalid PNG signature.".to_string()));
        }
    }
    if &data[0..8] != PNG_SIG {
        return Err(PngError("Invalid PNG signature.".to_string()));
    }
    let mut pos = 8usize;
    let mut ihdr: Option<(u32,u32,u8,u8,u8)> = None;
    let mut idat: Vec<u8> = Vec::new();
    let mut plte: Vec<(u8,u8,u8)> = Vec::new();
    let mut trns: Vec<u8> = Vec::new();
    let mut first_chunk = true;
    loop {
        if pos + 8 > data.len() {
            return Err(PngError("Unexpected end of data before image end.".to_string()));
        }
        let len = u32::from_be_bytes([data[pos],data[pos+1],data[pos+2],data[pos+3]]) as usize;
        let ctype = &data[pos+4..pos+8];
        if first_chunk && ctype != b"IHDR" {
            let name = chunk_type_debug(ctype);
            return Err(PngError(format!("{} chunk appeared before IHDR chunk", name)));
        }
        if pos + 8 + len + 4 > data.len() {
            return Err(PngError("Unexpected end of data before image end.".to_string()));
        }
        let chunk_data = &data[pos+8..pos+8+len];
        let stored_crc = u32::from_be_bytes([data[pos+8+len],data[pos+8+len+1],data[pos+8+len+2],data[pos+8+len+3]]);
        let mut crc_input = Vec::with_capacity(4+len);
        crc_input.extend_from_slice(ctype); crc_input.extend_from_slice(chunk_data);
        let computed = crc32(&crc_input);
        if computed != stored_crc {
            let name = chunk_type_debug(ctype);
            return Err(PngError(format!("CRC error: expected 0x{:08x} have 0x{:08x} while decoding {} chunk.", computed, stored_crc, name)));
        }
        match ctype {
            b"IHDR" => {
                if len < 13 { return Err(PngError("Unexpected end of data before image end.".to_string())); }
                let w = u32::from_be_bytes([chunk_data[0],chunk_data[1],chunk_data[2],chunk_data[3]]);
                let h = u32::from_be_bytes([chunk_data[4],chunk_data[5],chunk_data[6],chunk_data[7]]);
                ihdr = Some((w,h,chunk_data[8],chunk_data[9],chunk_data[12]));
            }
            b"PLTE" => {
                for i in (0..chunk_data.len()).step_by(3) {
                    if i+2 < chunk_data.len() { plte.push((chunk_data[i],chunk_data[i+1],chunk_data[i+2])); }
                }
            }
            b"tRNS" => { trns = chunk_data.to_vec(); }
            b"IDAT" => { idat.extend_from_slice(chunk_data); }
            b"IEND" => { break; }
            _ => {}
        }
        first_chunk = false;
        pos += 8 + len + 4;
        if ctype == b"IEND" { break; }
    }
    let (w,h,bit_depth,color_type,interlace) = ihdr.ok_or_else(|| PngError("Unexpected end of data before image end.".to_string()))?;
    if interlace == 1 {
        // Adam7 not supported by this reimplementation; treat as generic decode attempt below
        // Fall through: de-interlacing implemented via decode_raw with passes
    }
    // decompress
    use std::io::Read;
    let mut dec = flate2::read::ZlibDecoder::new(&idat[..]);
    let mut raw = Vec::new();
    if dec.read_to_end(&mut raw).is_err() {
        // distinguish: if idat data incomplete, png crate reports unexpected end / filter errors; use generic
        if raw.is_empty() {
            return Err(PngError("Unexpected end of data before image end.".to_string()));
        }
        // partial data may still parse; continue
    }
    let mut img = Image { width: w, height: h, data: vec![0; (w*h*4) as usize] };
    let channels = match color_type { 0 => 1, 2 => 3, 3 => 1, 4 => 2, 6 => 4, _ => {
        return Err(PngError(format!("Invalid PNG signature.")));
    }};
    if interlace == 1 {
        decode_interlaced(&raw, &mut img, w, h, bit_depth, color_type, channels, &plte, &trns)?;
    } else {
        decode_pass(&raw, &mut img, 0, 0, w, h, w, h, bit_depth, color_type, channels, &plte, &trns)?;
    }
    Ok(img)
}

fn chunk_type_debug(ctype: &[u8]) -> String {
    let name: String = ctype.iter().map(|&b| b as char).collect();
    let crit = ctype[0].is_ascii_uppercase();
    let privv = ctype[1].is_ascii_uppercase();
    let reserv = ctype[2].is_ascii_uppercase();
    let safe = ctype[3].is_ascii_lowercase();
    format!("ChunkType {{ type: {}, critical: {}, private: {}, reserved: {}, safecopy: {} }}", name, crit, privv, reserv, safe)
}

fn bytes_per_pixel(bit_depth: u8, channels: u32) -> usize {
    let bpp_bits = bit_depth as usize * channels as usize;
    (bpp_bits + 7) / 8
}
fn row_bytes(width: u32, bit_depth: u8, channels: u32) -> usize {
    ((width as usize * bit_depth as usize * channels as usize) + 7) / 8
}

fn decode_pass(raw: &[u8], img: &mut Image, x0: u32, y0: u32, pw: u32, ph: u32, full_w: u32, _full_h: u32, bit_depth: u8, color_type: u8, channels: u32, plte: &[(u8,u8,u8)], trns: &[u8]) -> Result<(), PngError> {
    if pw == 0 || ph == 0 { return Ok(()); }
    let rb = row_bytes(pw, bit_depth, channels);
    let bpp = bytes_per_pixel(bit_depth, channels).max(1);
    let mut pos = 0usize;
    let mut prev_row = vec![0u8; rb];
    // For interlaced passes, caller slices raw separately; for non-interlaced, raw includes all rows.
    // This function assumes raw starts at beginning of this pass (interlaced handled separately).
    for row_i in 0..ph {
        if pos >= raw.len() { return Err(PngError("Unexpected end of data before image end.".to_string())); }
        let filter = raw[pos]; pos += 1;
        if filter > 4 {
            return Err(PngError(format!("Unknown filter method {}.", filter)));
        }
        if pos + rb > raw.len() { return Err(PngError("Unexpected end of data before image end.".to_string())); }
        let mut row = raw[pos..pos+rb].to_vec(); pos += rb;
        unfilter(filter, &mut row, &prev_row, bpp);
        for col in 0..pw {
            let rgba = extract_pixel(&row, col as usize, bit_depth, color_type, channels, plte, trns);
            let gx = x0 + col; let gy = y0 + row_i;
            if gx < img.width && gy < img.height {
                let idx = ((gy*full_w + gx)*4) as usize;
                img.data[idx..idx+4].copy_from_slice(&rgba);
            }
        }
        prev_row = row;
    }
    Ok(())
}

fn decode_interlaced(raw: &[u8], img: &mut Image, w: u32, h: u32, bit_depth: u8, color_type: u8, channels: u32, plte: &[(u8,u8,u8)], trns: &[u8]) -> Result<(), PngError> {
    // Adam7 passes
    let passes = [(0u32,0u32,8u32,8u32),(4,0,8,8),(0,4,4,8),(2,0,4,4),(0,2,2,4),(1,0,2,2),(0,1,1,2)];
    let mut offset = 0usize;
    for (xs,ys,xs_step,ys_step) in passes {
        if xs >= w || ys >= h { continue; }
        let pw = (w - xs + xs_step - 1) / xs_step;
        let ph = (h - ys + ys_step - 1) / ys_step;
        let rb = row_bytes(pw, bit_depth, channels);
        let expected = (rb + 1) * ph as usize;
        if offset + expected > raw.len() && offset >= raw.len() {
            return Err(PngError("Unexpected end of data before image end.".to_string()));
        }
        let sub = &raw[offset..(offset+expected).min(raw.len())];
        // decode into temporary positioning: use decode_pass with x/y steps not supported, so decode manually
        decode_pass_step(sub, img, xs, ys, xs_step, ys_step, pw, ph, bit_depth, color_type, channels, plte, trns)?;
        offset += expected;
    }
    Ok(())
}

fn decode_pass_step(raw: &[u8], img: &mut Image, xs: u32, ys: u32, xstep: u32, ystep: u32, pw: u32, ph: u32, bit_depth: u8, color_type: u8, channels: u32, plte: &[(u8,u8,u8)], trns: &[u8]) -> Result<(), PngError> {
    let rb = row_bytes(pw, bit_depth, channels);
    let bpp = bytes_per_pixel(bit_depth, channels).max(1);
    let mut pos = 0usize;
    let mut prev = vec![0u8; rb];
    for r in 0..ph {
        if pos >= raw.len() { return Err(PngError("Unexpected end of data before image end.".to_string())); }
        let filter = raw[pos]; pos += 1;
        if filter > 4 { return Err(PngError(format!("Unknown filter method {}.", filter))); }
        if pos + rb > raw.len() { return Err(PngError("Unexpected end of data before image end.".to_string())); }
        let mut row = raw[pos..pos+rb].to_vec(); pos += rb;
        unfilter(filter, &mut row, &prev, bpp);
        for c in 0..pw {
            let rgba = extract_pixel(&row, c as usize, bit_depth, color_type, channels, plte, trns);
            let gx = xs + c*xstep; let gy = ys + r*ystep;
            if gx < img.width && gy < img.height {
                let idx = ((gy*img.width + gx)*4) as usize;
                img.data[idx..idx+4].copy_from_slice(&rgba);
            }
        }
        prev = row;
    }
    Ok(())
}

fn unfilter(filter: u8, row: &mut [u8], prev: &[u8], bpp: usize) {
    match filter {
        0 => {},
        1 => { for i in bpp..row.len() { row[i] = row[i].wrapping_add(row[i-bpp]); } },
        2 => { for i in 0..row.len() { row[i] = row[i].wrapping_add(prev[i]); } },
        3 => {
            for i in 0..row.len() {
                let a = if i >= bpp { row[i-bpp] } else { 0 };
                row[i] = row[i].wrapping_add(((a as u16 + prev[i] as u16)/2) as u8);
            }
        },
        4 => {
            for i in 0..row.len() {
                let a = if i >= bpp { row[i-bpp] } else { 0 };
                let b = prev[i];
                let c = if i >= bpp { prev[i-bpp] } else { 0 };
                row[i] = row[i].wrapping_add(paeth(a,b,c));
            }
        },
        _ => {}
    }
}
fn paeth(a:u8,b:u8,c:u8) -> u8 {
    let a = a as i32; let b = b as i32; let c = c as i32;
    let p = a + b - c; let pa = (p-a).abs(); let pb = (p-b).abs(); let pc = (p-c).abs();
    if pa <= pb && pa <= pc { a as u8 } else if pb <= pc { b as u8 } else { c as u8 }
}

fn extract_pixel(row: &[u8], col: usize, bit_depth: u8, color_type: u8, _channels: u32, plte: &[(u8,u8,u8)], trns: &[u8]) -> [u8;4] {
    // returns RGBA
    match (color_type, bit_depth) {
        (6, 8) => { let i = col*4; [row[i], row[i+1], row[i+2], row[i+3]] },
        (6, 16) => { let i = col*8; [row[i], row[i+2], row[i+4], row[i+6]] },
        (2, 8) => { let i = col*3; [row[i], row[i+1], row[i+2], 255] },
        (2, 16) => { let i = col*6; [row[i], row[i+2], row[i+4], 255] },
        (0, 8) => { let v = row[col]; [v,v,v,255] },
        (0, 16) => { let v = row[col*2]; [v,v,v,255] },
        (4, 8) => { let i = col*2; let v=row[i]; [v,v,v,row[i+1]] },
        (4, 16) => { let i = col*4; let v=row[i]; [v,v,v,row[i+2]] },
        (3, 8) => {
            let idx = row[col] as usize;
            let (r,g,b) = plte.get(idx).copied().unwrap_or((0,0,0));
            let a = trns.get(idx).copied().unwrap_or(255);
            [r,g,b,a]
        },
        (3, bd) if bd < 8 => {
            let per_byte = 8 / bd;
            let byte = row[col / per_byte as usize];
            let shift = 8 - bd*( (col % per_byte as usize) as u8 + 1);
            let mask = ((1u16 << bd) - 1) as u8;
            let idx = ((byte >> shift) & mask) as usize;
            let (r,g,b) = plte.get(idx).copied().unwrap_or((0,0,0));
            let a = trns.get(idx).copied().unwrap_or(255);
            [r,g,b,a]
        },
        (0, bd) if bd < 8 => {
            let per_byte = 8 / bd;
            let byte = row[col / per_byte as usize];
            let shift = 8 - bd*( (col % per_byte as usize) as u8 + 1);
            let mask = ((1u16 << bd) - 1) as u8;
            let idx = ((byte >> shift) & mask) as usize;
            let max = ((1u16 << bd)-1) as u8;
            let v = (idx as u16 * 255 / max as u16) as u8;
            [v,v,v,255]
        },
        _ => [0,0,0,255],
    }
}
