impl std::error::Error for PngError {}

pub type Color = (u8, u8, u8, u8);

pub fn blend_over(dst: &mut [u8], src: Color) {
    let sa = src.3 as f32 / 255.0;
    if sa <= 0.0 { return; }
    if sa >= 1.0 {
        dst[0] = src.0; dst[1] = src.1; dst[2] = src.2; dst[3] = 255; return;
    }
    let da = dst[3] as f32 / 255.0;
    let out_a = sa + da * (1.0 - sa);
    if out_a <= 0.0 { dst[0]=0; dst[1]=0; dst[2]=0; dst[3]=0; return; }
    for i in 0..3 {
        let s = [src.0, src.1, src.2][i] as f32;
        let d = dst[i] as f32;
        dst[i] = ((s * sa + d * da * (1.0 - sa)) / out_a).round().clamp(0.0,255.0) as u8;
    }
    dst[3] = (out_a * 255.0).round().clamp(0.0,255.0) as u8;
}

// Parse a hex colour; panics are emulated by the caller (see color parsing helper in main)
pub fn hex_to_rgba(s: &str) -> Option<Color> {
    // assumes validated format #RRGGBB or #RRGGBBAA
    if !s.starts_with('#') { return None; }
    let h = &s[1..];
    let parse = |i: usize| u8::from_str_radix(&h[i..i+2], 16).ok();
    match h.len() {
        6 => Some((parse(0)?, parse(2)?, parse(4)?, 255)),
        8 => Some((parse(0)?, parse(2)?, parse(4)?, parse(6)?)),
        _ => None,
    }
}

impl Image {
    pub fn new(width: u32, height: u32) -> Option<Image> {
        if width == 0 || height == 0 { return None; }
