pub fn lang_for_path(path: &str) -> Option<Lang> {
    let base = path.rsplit('/').next().unwrap_or(path);
    if let Some(l) = special_filename(base) { return Some(l); }
    // hidden file with single dot: no extension
    let dot_count = base.matches('.').count();
    if base.starts_with('.') && dot_count <= 1 { return None; }
    let ext = base.rsplit('.').next()?;
    if ext == base { return None; } // no dot
    lang_for_extension(&ext.to_lowercase())
}

pub fn lang_for_token(token: &str) -> Option<Lang> {
    let t = token.to_lowercase();
    // by name
    let by_name = match t.as_str() {
