fn is_ident_start(c: char) -> bool { c.is_alphabetic() || c == '_' || c == '$' }
fn is_ident_cont(c: char) -> bool { c.is_alphanumeric() || c == '_' || c == '$' }

#[derive(Clone, Copy, PartialEq)]
enum State { Normal, BlockComment, TripleString(char) }

pub struct Highlighter {
    pub lang: Lang,
    state: State,
    expect_name: bool, // after def/class/function etc: next identifier is a function/type name
}
impl Highlighter {
    pub fn new(lang: Lang) -> Self { Self { lang, state: State::Normal, expect_name: false } }
    // Returns segments for one line: Vec<(text, color)>
    pub fn highlight_line(&mut self, line: &str) -> Vec<(String, Color)> {
        if self.lang == Lang::Plain {
            return vec![(line.to_string(), FG)];
        }
        if self.lang == Lang::Html {
            return highlight_html(line);
        }
        let mut segs: Vec<(String, Color)> = Vec::new();
        let chars: Vec<char> = line.chars().collect();
        let mut i = 0usize;
        let mut push = |segs: &mut Vec<(String,Color)>, text: String, color: Color| {
            if text.is_empty() { return; }
            if let Some(last) = segs.last_mut() {
                if last.1 == color { last.0.push_str(&text); return; }
            }
            segs.push((text, color));
        };
        while i < chars.len() {
            match self.state {
                State::BlockComment => {
                    // consume till */
                    let rest: String = chars[i..].iter().collect();
                    if let Some(pos) = rest.find("*/") {
                        // find char index of */
                        let bytepos = pos;
                        let charpos = rest[..bytepos].chars().count();
                        let end = i + charpos + 2;
                        let text: String = chars[i..end.min(chars.len())].iter().collect();
                        push(&mut segs, text, COMMENT);
                        i = end; self.state = State::Normal;
                    } else {
                        push(&mut segs, rest, COMMENT);
                        i = chars.len();
                    }
                    continue;
                }
                State::TripleString(q) => {
                    let rest: String = chars[i..].iter().collect();
                    let term = if q == '"' { "\"\"\"" } else { "'''" };
                    if let Some(pos) = rest.find(term) {
                        let charpos = rest[..pos].chars().count();
                        let end = i + charpos + 3;
                        let text: String = chars[i..end.min(chars.len())].iter().collect();
                        push(&mut segs, text, STRING);
                        i = end; self.state = State::Normal;
                    } else {
                        push(&mut segs, rest, STRING);
                        i = chars.len();
                    }
                    continue;
                }
                State::Normal => {}
            }
            let c = chars[i];
            let rest: String = chars[i..].iter().collect();
            // block comment start
            if rest.starts_with("/*") {
                self.state = State::BlockComment;
                push(&mut segs, "/*".to_string(), COMMENT);
                i += 2; continue;
            }
            if rest.starts_with("<!--") {
                // html-style comment, consume to --> or EOL
                push(&mut segs, rest.clone(), COMMENT);
                break;
            }
            // line comments
            if let Some(lc) = self.lang.line_comment() {
                if rest.starts_with(lc) {
                    push(&mut segs, rest.clone(), COMMENT);
                    break;
                }
            }
            if self.lang == Lang::Python && rest.starts_with('#') {
                push(&mut segs, rest.clone(), COMMENT); break;
            }
            // python triple string
            if self.lang == Lang::Python && (rest.starts_with("\"\"\"") || rest.starts_with("'''")) {
                let q = chars[i];
                // check if ends on same line
                let term = if q=='"' { "\"\"\"" } else { "'''" };
                if let Some(pos) = rest[3..].find(term) {
                    let charpos = rest[3..][..pos].chars().count();
                    let end = i + 3 + charpos + 3;
                    let text: String = chars[i..end.min(chars.len())].iter().collect();
                    push(&mut segs, text, STRING);
                    i = end;
                } else {
                    push(&mut segs, rest.clone(), STRING);
                    self.state = State::TripleString(q);
                    break;
                }
                continue;
            }
            // strings
            if c == '"' || c == '\'' || c == '`' {
                let q = c;
                let mut j = i + 1;
                let mut text = String::new(); text.push(chars[i]);
                while j < chars.len() {
                    text.push(chars[j]);
                    if chars[j] == '\\' && j + 1 < chars.len() { j += 1; text.push(chars[j]); j += 1; continue; }
                    if chars[j] == q { j += 1; break; }
                    j += 1;
                }
                push(&mut segs, text, STRING);
                i = j; continue;
            }
            // numbers
            if c.is_ascii_digit() {
                let mut j = i;
                let mut text = String::new();
                // hex etc
                while j < chars.len() && (chars[j].is_alphanumeric() || chars[j] == '.' || chars[j] == '_') {
                    text.push(chars[j]); j += 1;
                }
                push(&mut segs, text, NUMBER);
                i = j; continue;
            }
            // identifiers
            if is_ident_start(c) {
                let mut j = i; let mut text = String::new();
                while j < chars.len() && is_ident_cont(chars[j]) { text.push(chars[j]); j += 1; }
                let color = if self.expect_name {
                    self.expect_name = false; FUNCTION
                } else if self.lang.keywords().contains(&text.as_str()) || (self.lang==Lang::Sql && self.lang.keywords().contains(&text.to_uppercase().as_str())) {
                    if matches!(text.as_str(), "def"|"class"|"fn"|"function"|"struct"|"enum"|"trait"|"interface"|"impl") { self.expect_name = true; }
                    KEYWORD
                } else if text.as_str() == "True" || text.as_str() == "False" || text.as_str() == "None" || text.as_str() == "true" || text.as_str() == "false" || text.as_str() == "null" || text.as_str() == "nil" {
                    NUMBER
                } else if self.lang.builtins().contains(&text.as_str()) {
                    TYPE
                } else {
                    // function call?
                    let mut k = j;
                    while k < chars.len() && chars[k] == ' ' { k += 1; }
                    if k < chars.len() && chars[k] == '(' { FUNCTION }
                    else if text.chars().next().map(|ch| ch.is_uppercase()).unwrap_or(false) { TYPE }
                    else { FG }
                };
                // keyword may set expect_name (already handled for def...); also "class"
                push(&mut segs, text, color);
                i = j; continue;
            }
            // decorator / attribute
            if c == '@' || c == '#' && self.lang == Lang::Rust {
                let mut j = i+1; let mut text = String::from(c);
                while j < chars.len() && is_ident_cont(chars[j]) { text.push(chars[j]); j+=1; }
                push(&mut segs, text, FUNCTION);
                i = j; continue;
            }
            // single char
            push(&mut segs, c.to_string(), FG);
            i += 1;
        }
        if segs.is_empty() { segs.push((String::new(), FG)); }
        segs
    }
}

fn highlight_html(line: &str) -> Vec<(String, Color)> {
    // very small approximation
    let mut segs = Vec::new();
    let mut i = 0; let chars: Vec<char> = line.chars().collect();
    while i < chars.len() {
        if chars[i] == '<' {
            let mut j = i; let mut text = String::new();
            while j < chars.len() && chars[j] != '>' { text.push(chars[j]); j+=1; }
            if j < chars.len() { text.push('>'); j+=1; }
            // split tag inner: colour whole tag pink-ish, strings already inside will be blended
            // simplistic: if contains quotes, highlight quoted parts yellow by re-splitting
            let mut cur = String::new(); let mut in_q: Option<char> = None;
            for ch in text.chars() {
                if let Some(q) = in_q {
                    cur.push(ch);
                    if ch == q { segs.push((std::mem::take(&mut cur), STRING)); in_q = None; }
                } else if ch == '"' || ch == '\'' {
                    if !cur.is_empty() { segs.push((std::mem::take(&mut cur), KEYWORD)); }
                    cur.push(ch); in_q = Some(ch);
                } else { cur.push(ch); }
            }
            if !cur.is_empty() { segs.push((cur, if in_q.is_some() { STRING } else { KEYWORD })); }
            i = j;
        } else if chars[i] == '"' || chars[i] == '\'' {
            let q = chars[i]; let mut j = i; let mut text = String::new();
            loop { if j>=chars.len() {break;} text.push(chars[j]); if chars[j]==q && j>i {j+=1; break;} j+=1; }
            segs.push((text, STRING)); i=j;
        } else {
            let mut j=i; let mut text=String::new();
            while j<chars.len() && chars[j] != '<' { text.push(chars[j]); j+=1; }
            segs.push((text, FG)); i=j;
        }
    }
    if segs.is_empty() { segs.push((String::new(), FG)); }
    segs
}
RUST
"}

