                    if ch == q { segs.push((std::mem::take(&mut cur), STRING)); in_q = None; }
                } else if ch == '"' || ch == '\'' {
                    if !cur.is_empty() { segs.push((std::mem::take(&mut cur), KEYWORD)); }
                    cur.push(ch); in_q = Some(ch);
                } else { cur.push(ch); }
            }
            if !cur.is_empty() { segs.push((cur, if in_q.is_some() { STRING } else { KEYWORD })); }
            i = j;
        } else if chars[i] == '"' || chars[i] == '\'' {
            let q = chars[i]; let mut j = i; let mut text = String::new();
            loop { if j>=chars.len() {break;} text.push(chars[j]); if chars[j]==q && j>i {j+=1; break;} j+=1; }
            segs.push((text, STRING)); i=j;
        } else {
            let mut j=i; let mut text=String::new();
            while j<chars.len() && chars[j] != '<' { text.push(chars[j]); j+=1; }
            segs.push((text, FG)); i=j;
        }
    }
    if segs.is_empty() { segs.push((String::new(), FG)); }
    segs
}
