fn clipboard_error() -> String {
    "Unknown error while interacting with the clipboard: X11 server connection timed out because it was unreachable".to_string()
}

fn try_clipboard_get_text() -> Result<String, String> {
    // If a clipboard tool is available on a graphical session, try it; otherwise mirror headless error.
    let has_display = std::env::var("DISPLAY").is_ok() || std::env::var("WAYLAND_DISPLAY").is_ok();
    if has_display {
        for (prog, args) in [("xclip", vec!["-o", "-selection", "clipboard"]), ("xsel", vec!["--clipboard", "--output"]), ("wl-paste", vec![])] {
            if let Ok(out) = std::process::Command::new(prog).args(&args).output() {
                if out.status.success() {
                    return String::from_utf8(out.stdout).map_err(|e| e.to_string());
                }
            }
        }
    }
    Err(clipboard_error())
}
fn try_clipboard_set_image(png: &[u8], width: u32, height: u32) -> Result<(), String> {
    let _ = (png, width, height);
    let has_display = std::env::var("DISPLAY").is_ok() || std::env::var("WAYLAND_DISPLAY").is_ok();
    if has_display {
        for (prog, args) in [("xclip", vec!["-selection", "clipboard", "-t", "image/png"]), ("wl-copy", vec!["--type", "image/png"])] {
            if let Ok(mut child) = std::process::Command::new(prog).args(&args).stdin(std::process::Stdio::piped()).spawn() {
                if let Some(mut stdin) = child.stdin.take() {
                    use std::io::Write; let _ = stdin.write_all(png);
                }
                if let Ok(status) = child.wait() { if status.success() { return Ok(()); } }
            }
        }
    }
    Err(clipboard_error())
}
fn try_clipboard_set_text(text: &str) -> Result<(), String> {
    let has_display = std::env::var("DISPLAY").is_ok() || std::env::var("WAYLAND_DISPLAY").is_ok();
    if has_display {
        for (prog, args) in [("xclip", vec!["-selection", "clipboard"]), ("xsel", vec!["--clipboard", "--input"]), ("wl-copy", vec![])] {
            if let Ok(mut child) = std::process::Command::new(prog).args(&args).stdin(std::process::Stdio::piped()).spawn() {
                if let Some(mut stdin) = child.stdin.take() { use std::io::Write; let _ = stdin.write_all(text.as_bytes()); }
                if let Ok(status) = child.wait() { if status.success() { return Ok(()); } }
            }
        }
    }
    Err(clipboard_error())
}

