// ---------- Raw highlight parsing ----------
#[derive(Deserialize, Debug)]
#[serde(untagged)]
enum HighlightLineRaw {
    Single { 0: u32, 1: String },
    // untagged enum variants as tuples are not directly expressible; use custom below
}
#[derive(Debug, Clone)]
enum RawHighlight {
    Single(usize, String),
    Range(usize, usize, String),
}
fn parse_raw_highlights(s: &str) -> Result<Vec<RawHighlight>, String> {
    // Match serde_json untagged enum behaviour & error messages approximately using serde types.
    // Deserialize into Vec<Vec<serde_json::Value>> first with strict shape checks mirroring the enum.
    let value: serde_json::Value = serde_json::from_str(s).map_err(|e| e.to_string())?;
    // expected type: a sequence of sequences; first try whole parse through a helper serde structure
    // Use serde to validate untagged enum shape and produce serde messages for common failures:
    #[derive(Deserialize)]
    #[serde(untagged)]
    enum HL {
        S(usize, String),
        R(usize, usize, String),
    }
    // Re-parse via serde on each element to reuse error messages:
    let arr = match value.as_array() {
        Some(a) => a.clone(),
        None => {
            // produce serde-like error for non-sequence input
            let _: Vec<HL> = serde_json::from_str(s).map_err(|e| e.to_string())?;
            return Err("data did not match any variant of untagged enum HighlightLine".to_string());
        }
    };
    let mut out = Vec::new();
    for item in &arr {
        let text = item.to_string();
        match serde_json::from_str::<HL>(&text) {
            Ok(HL::S(n, c)) => out.push(RawHighlight::Single(n as usize, c)),
            Ok(HL::R(a, b, c)) => out.push(RawHighlight::Range(a as usize, b as usize, c)),
            Err(_) => {
                // Recreate the serde error for the outer Vec<HL> to get column-accurate message
                let _: Vec<HL> = serde_json::from_str(s).map_err(|e| e.to_string())?;
                return Err("data did not match any variant of untagged enum HighlightLine".to_string());
            }
        }
    }
    Ok(out)
}

