fn log_error(msg: &str) { println!("\x1b[31m[ERROR]\x1b[0m {}", msg); }

// ---------- panic emulation ----------
fn panic_emulate(location: &str, message: &str) -> ! {
    let pid = std::process::id();
    let bt = std::env::var("RUST_BACKTRACE").unwrap_or_default();
    if bt == "1" || bt == "full" {
        eprintln!("\nthread 'main' ({}) panicked at {}:\n{}\nstack backtrace:\nnote: Some details are omitted, run with `RUST_BACKTRACE=full` for a verbose backtrace.", pid, location, message);
    } else {
        eprintln!("\nthread 'main' ({}) panicked at {}:\n{}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace", pid, location, message);
    }
    std::process::exit(101);
}

pub fn parse_color(s: &str) -> Color {
    let bytes = s.as_bytes();
    if !(bytes.len() == 7 || bytes.len() == 9) || bytes.first() != Some(&b'#') {
        panic_emulate("core/src/utils/color.rs:32:13", &format!("Invalid hex color: {}", s));
    }
    let hex = &s[1..];
    let parse_pair = |i: usize| -> u8 {
        match u8::from_str_radix(&hex[i..i+2], 16) {
            Ok(v) => v,
            Err(_) => panic_emulate("core/src/utils/color.rs:41:85", "called `Result::unwrap()` on an `Err` value: ParseIntError { kind: InvalidDigit }"),
        }
    };
    if hex.len() == 6 {
        (parse_pair(0), parse_pair(2), parse_pair(4), 255)
    } else {
        (parse_pair(0), parse_pair(2), parse_pair(4), parse_pair(6))
    }
}

