        .arg(Arg::new("background").long("background").value_name("BACKGROUND").help("Set background color of the snapshot"))
        .arg(Arg::new("r#type").long("type").value_name("TYPE").value_parser(["ascii", "image"]).default_value("image").help(""))
        .arg(Arg::new("config").long("config").value_name("CONFIG").help(""));
