}

// ---------- config loading ----------
fn home_dir_path() -> Option<PathBuf> {
    if let Ok(h) = std::env::var("HOME") {
        if !h.is_empty() { return Some(PathBuf::from(h)); }
    }
    // fall back to passwd entry
    unsafe {
        #[repr(C)]
        struct Passwd { pw_name: *const std::os::raw::c_char, pw_passwd: *const std::os::raw::c_char, pw_uid: u32, pw_gid: u32, pw_gecos: *const std::os::raw::c_char, pw_dir: *const std::os::raw::c_char, pw_shell: *const std::os::raw::c_char }
        extern "C" { fn getuid() -> u32; fn getpwuid(uid: u32) -> *mut Passwd; }
        let uid = getuid();
        let pw = getpwuid(uid);
        if !pw.is_null() && !(*pw).pw_dir.is_null() {
            let s = std::ffi::CStr::from_ptr((*pw).pw_dir).to_string_lossy().to_string();
            if !s.is_empty() { return Some(PathBuf::from(s)); }
        }
    }
    None
}

fn load_config(cli_config: Option<&String>) -> Result<CodeSnapCLIConfig, String> {
    let path: PathBuf = if let Some(p) = cli_config {
        PathBuf::from(p)
    } else if let Some(home) = home_dir_path() {
        home.join(".config").join("codesnap").join("config.json")
    } else {
        // no home: parse default
        let cfg: CodeSnapCLIConfig = serde_json::from_str(DEFAULT_CONFIG_JSON).map_err(|e| e.to_string())?;
        return Ok(cfg);
    };
    let is_default_path = cli_config.is_none();
    if is_default_path && !path.exists() {
        // create default config
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent).map_err(|e| e.to_string())?;
            let _ = std::fs::create_dir_all(parent.join("remote_themes"));
        }
        std::fs::write(&path, DEFAULT_CONFIG_JSON).map_err(|e| e.to_string())?;
        log_info(&format!("Automated created config file at {:?}", path.display().to_string()));
    }
    let contents = std::fs::read_to_string(&path).map_err(|e| e.to_string())?;
    let cfg: CodeSnapCLIConfig = serde_json::from_str(&contents).map_err(|e| e.to_string())?;
    if cfg.snapshot_config.background.is_none() {
        return Err("`background` must be initialized".to_string());
    }
    Ok(cfg)
}

// ---------- range parsing ----------
fn parse_usize(s: &str) -> Result<usize, String> {
    s.parse::<usize>().map_err(|e: std::num::ParseIntError| e.to_string())
}
// Parses "a:b", ":b", "a:", ":" -> mirrors observed behaviour
fn parse_range(range: &str, total: usize) -> Result<(usize, usize), String> {
    let parts: Vec<&str> = range.split(':').collect();
    if parts.len() != 2 {
        return Err("Invalid range format".to_string());
    }
    let (a, b) = (parts[0], parts[1]);
    let start: usize;
    let end: usize;
    if a.is_empty() && b.is_empty() {
        // mirrors the original: parsing an empty string fails
        start = parse_usize(a)?;
        end = total;
    } else if a.is_empty() {
        start = 1;
        end = parse_usize(b)?;
    } else if b.is_empty() {
        start = parse_usize(a)?;
        end = total;
    } else {
        start = parse_usize(a)?;
        end = parse_usize(b)?;
    }
    Ok((start, end))
}

fn split_code_lines(code: &str) -> Vec<String> {
    // strip exactly one trailing line terminator
    let mut s = code;
    if s.ends_with("\r\n") { s = &s[..s.len()-2]; }
    else if s.ends_with('\n') || s.ends_with('\r') { s = &s[..s.len()-1]; }
    // split on \r\n, \n, \r (Rust .lines-like but including lone \r)
    let mut lines = Vec::new();
    let mut cur = String::new();
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '\r' || c == '\n' {
            lines.push(cur.clone()); cur.clear();
            if c == '\r' && i + 1 < chars.len() && chars[i+1] == '\n' { i += 1; }
            // a trailing terminator should not add a final empty line: handled by checking below
            if i == chars.len() - 1 {
                // terminator at very end: do not push extra
                i += 1;
                // mark that we ended with terminator by a flag via lines content: we already pushed.
                // To match .lines() behaviour, nothing more.
                return if lines.is_empty() { vec![String::new()] } else { lines };
            }
        } else { cur.push(c); }
        i += 1;
    }
    lines.push(cur);
    if lines.is_empty() { lines.push(String::new()); }
    lines
}

// dedent lines: expand tabs to 2 spaces; strip common indent (chars count)
fn dedent_lines(lines: &[String]) -> Vec<String> {
    let expanded: Vec<String> = lines.iter().map(|l| l.replace('\t', "  ")).collect();
    if expanded.is_empty() { return expanded; }
    // indent of a line = position of first non-whitespace char; blank lines count as 0
    let mut min_indent = usize::MAX;
    for l in &expanded {
        let ind = l.chars().position(|c| !c.is_whitespace()).unwrap_or(0);
        if ind < min_indent { min_indent = ind; }
    }
    if min_indent == usize::MAX || min_indent == 0 { return expanded; }
    expanded.iter().map(|l| {
        let chars: Vec<char> = l.chars().collect();
        if chars.len() >= min_indent { chars[min_indent..].iter().collect() } else { String::new() }
    }).collect()
}

