    let seed = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map(|d| d.subsec_nanos() as usize ^ (std::process::id() as usize * 2654435761)).unwrap_or(0);
    let msg = messages[seed % messages.len()];
    let border_len = msg.len() + 2;
