fn axis_value(axis: &PointAxis, max: f32) -> f32 {
    match axis { PointAxis::Number(n) => *n, PointAxis::Max(_) => max }
}

fn draw_background(img: &mut Image, bg: &Background, logical_w: f32, logical_h: f32, scale: f32) {
    match bg {
        Background::Color(s) => {
            let col = parse_color(s);
            // fill all pixels
            for y in 0..img.height { for x in 0..img.width { img.set_blend(x as i32, y as i32, col); } }
            let _ = (logical_w, logical_h, scale);
        }
        Background::Gradient(g) => {
            if g.stops.is_empty() {
                panic_emulate("core/src/components/background.rs:80:18", "called `Option::unwrap()` on a `None` value");
            }
            let stops: Vec<(f32, Color)> = g.stops.iter().map(|s| (s.position, parse_color(&s.color))).collect();
            let total_w = img.width as f32; let total_h = img.height as f32;
            let sx = axis_value(&g.start.x, logical_w) * scale;
            let sy = axis_value(&g.start.y, logical_h) * scale;
            let ex = axis_value(&g.end.x, logical_w) * scale;
            let ey = axis_value(&g.end.y, logical_h) * scale;
            let dx = ex - sx; let dy = ey - sy;
            let len2 = dx*dx + dy*dy;
            for y in 0..img.height {
                for x in 0..img.width {
                    let t = if len2 == 0.0 { 0.0 } else { (((x as f32 - sx)*dx + (y as f32 - sy)*dy) / len2).clamp(0.0, 1.0) };
                    let col = image::interpolate_stops(&stops, t);
                    img.set_blend(x as i32, y as i32, col);
                }
            }
            let _ = (total_w, total_h);
        }
    }
}

fn draw_shadow(img: &mut Image, wx: f32, wy: f32, ww: f32, wh: f32, radius: f32, shadow_radius: f32, shadow_color_str: &str) {
    let scol = parse_color(shadow_color_str);
    if scol.3 == 0 { return; }
    // build alpha mask
    let w = img.width as usize; let h = img.height as usize;
    let mut mask = vec![0f32; w*h];
    let offset_y = 6.0f32; // subtle drop
    // offset shadow area by scaled amounts represented in pixel space by caller scaling inputs
    for y in 0..h as i32 {
        for x in 0..w as i32 {
            // rounded rect coverage at shadow rect
            let px = x as f32 + 0.5; let py = y as f32 + 0.5 - offset_y;
            // compute coverage via same distance function indirectly: point inside check
            let cov = rounded_cov(px, py + offset_y, wx, wy + offset_y, ww, wh, radius);
            if cov > 0.0 { mask[y as usize * w + x as usize] = cov * (scol.3 as f32 / 255.0); }
        }
    }
    let blur_r = ((shadow_radius / 2.0) as usize).max(0);
    if blur_r > 0 { image::box_blur_alpha(&mut mask, w, h, blur_r); }
    for y in 0..h {
        for x in 0..w {
            let a = mask[y*w+x];
            if a > 0.0 {
                let ca = (255.0 * a).round().clamp(0.0,255.0) as u8;
                img.set_blend(x as i32, y as i32, (scol.0, scol.1, scol.2, ca));
            }
        }
    }
}

fn rounded_cov(px: f32, py: f32, x: f32, y: f32, w: f32, h: f32, r: f32) -> f32 {
    let r = r.min(w/2.0).min(h/2.0).max(0.0);
    let cx = x + w/2.0; let cy = y + h/2.0;
    let qx = (px - cx).abs() - (w/2.0 - r);
    let qy = (py - cy).abs() - (h/2.0 - r);
    let ax = qx.max(0.0); let ay = qy.max(0.0);
    let sd = (ax*ax + ay*ay).sqrt() + qx.max(qy).min(0.0) - r;
    (0.5 - sd).clamp(0.0, 1.0)
}

fn make_canvas(logical_w: f32, logical_h: f32, scale: u8) -> Image {
    let s = scale as f32;
    let w = (logical_w * s) as u32; // trunc like `as`
    let h = (logical_h * s) as u32;
    match Image::new(w, h) {
        Some(im) => im,
        None => panic_emulate("core/src/components/container.rs:34:10", "called `Option::unwrap()` on a `None` value"),
    }
}

// render code snapshot; returns image
fn render_code(
    params: &RenderParams,
    raw_code: &str,
    source_file: Option<&str>,
    cli_file_path: Option<&str>,
    cli_language: Option<&str>,
    code_range_opt: Option<&str>,
    highlight_range_opt: Option<&str>,
    relative_highlight: bool,
    highlight_range_color: &str,
    raw_highlight_opt: Option<&str>,
    delete_lines: &[String],
    delete_color: &str,
    add_lines: &[String],
    add_color: &str,
) -> Result<Image, String> {
    // 1. Range parsing & slicing
    let all_lines = split_code_lines(raw_code);
    let total_original = all_lines.len();
    let mut range_start = 1usize; let mut range_end = total_original;
    let mut selected_indices: Vec<usize> = (0..total_original).collect(); // 0-based indexes into all_lines (original line i+1)
    if let Some(r) = code_range_opt {
        let (mut a, mut b) = parse_range(r, total_original)?;
        if a > b { std::mem::swap(&mut a, &mut b); }
        range_start = a; range_end = b;
        // select using skip(a-1) semantics where a==0 wraps to huge (empty)
        let skip_n = a.wrapping_sub(1);
        let take_n = if b >= a { b - a + 1 } else { 0 };
        selected_indices = (0..total_original).skip(skip_n).take(take_n).collect();
        // when skip wraps, iterator is empty -> results in a single blank displayed line handled below
    }
    let selected_lines_raw: Vec<String> = if selected_indices.is_empty() { vec![String::new()] } else { selected_indices.iter().map(|&i| all_lines[i].clone()).collect() };
    let displayed_count = selected_lines_raw.len();
    // dedent
    let lines = dedent_lines(&selected_lines_raw);

    // 2. Raw highlights (parse JSON and colours first)
    let mut raw_entries: Vec<RawHighlight> = Vec::new();
    if let Some(raw_s) = raw_highlight_opt {
        raw_entries = parse_raw_highlights(raw_s)?;
        for e in &raw_entries {
            match e { RawHighlight::Single(_, c) => { parse_color(c); }, RawHighlight::Range(_,_,c) => { parse_color(c); } }
        }
    }
    // 3. Parse highlight_range / delete / add & validate
    let mut entries: Vec<HighlightEntry> = Vec::new();
    if let Some(hr) = highlight_range_opt {
        let (mut a, mut b) = parse_range(hr, total_original)?;
        if a > b { std::mem::swap(&mut a, &mut b); }
        entries.push(HighlightEntry { start: a, end: b, color_str: highlight_range_color.to_string(), is_raw: false });
    }
    let mut delete_nums: Vec<usize> = Vec::new();
    for d in delete_lines { delete_nums.push(parse_usize(d)?); }
    for &n in &delete_nums { entries.push(HighlightEntry { start: n, end: n, color_str: delete_color.to_string(), is_raw: false }); }
    // add entries after delete (both validated together below; rendering order is highlight, delete, add as separate passes)
    let mut add_nums: Vec<usize> = Vec::new();
    for a in add_lines { add_nums.push(parse_usize(a)?); }
    // validation: need delete and add entries validated too, in order highlight, deletes, adds
    let mut validate_list: Vec<(usize,usize)> = Vec::new();
    if let Some(e) = entries.first() { if highlight_range_opt.is_some() { validate_list.push((e.start, e.end)); } }
    for &n in &delete_nums { validate_list.push((n,n)); }
    for &n in &add_nums { validate_list.push((n,n)); }
    for (a,b) in &validate_list {
        if relative_highlight {
            // allowed end is displayed_count; start check is 0-based (0 always passes)
            if *b > displayed_count {
                let msg_end = range_end.wrapping_sub(range_start);
                return Err(format!("The highlight end range should be less than or equal to {}", msg_end));
            }
        } else {
            if *a < range_start {
                return Err(format!("The highlight start range should be greater than or equal to {}", range_start));
            }
            if *b > range_end {
                return Err(format!("The highlight end range should be less than or equal to {}", range_end));
            }
        }
    }
    // 4. scale validation
    if params.scale < 1 {
        return Err("The scale factor must be greater than 1 ".to_string());
    }
    // 5. theme
    if params.theme != "candy" {
        return Err(format!("Cannot find {} theme", params.theme));
    }
    // 6. language
    let lang = if let Some(l) = cli_language {
        syntax::lang_for_token(l).unwrap_or(syntax::Lang::Plain)
    } else if source_file.is_some() {
        syntax::lang_for_path(source_file.unwrap()).unwrap_or(syntax::Lang::Plain)
    } else if let Some(fp) = cli_file_path {
        match syntax::lang_for_path(fp) {
            Some(l) => l,
            None => return Err(format!("No such file {}", fp)),
        }
    } else { syntax::Lang::Plain };
    // breadcrumb path
    let breadcrumb_path: Option<String> = if params.breadcrumbs_enable {
        if let Some(fp) = cli_file_path { Some(fp.to_string()) }
        else if let Some(sf) = source_file { Some(sf.to_string()) }
        else { None }
    } else { None };

    // --- layout ---
    let s = params.scale as f32;
    let line_height = 18.0f32;
    let code_size = 12.2f32 * s;
    let mut renderer = font::TextRenderer::new();
    // content width in logical units
    let gutter_logical: f32 = if params.has_line_number {
        let start_num = params.start_line_number.map(|v| v as usize).unwrap_or(range_start);
        let max_num = start_num + displayed_count.saturating_sub(1);
        let digits = max_num.to_string().len() as f32;
        10.0 + 9.0 * digits
    } else { 0.0 };
    let mut content_w = 0.0f32;
    {
        // measure code lines in logical terms (measure at scaled size and divide by scale)
        for line in &lines {
            let wpx = renderer.width(font::FontKind::Mono, &params.code_font, line, code_size);
            content_w = content_w.max(wpx / s);
        }
        content_w += gutter_logical;
    }
    if let Some(bp) = &breadcrumb_path {
        let bc_size = 13.3f32 * s;
        let wpx = renderer.width(font::FontKind::Mono, &params.code_font, bp, bc_size);
        content_w = content_w.max(wpx / s);
    }
    if let Some(t) = &params.title {
        let tsize = 11.5f32 * s;
        // title font special: Pacifico falls back to sans in title component
        let fam = if params.title_font.trim().eq_ignore_ascii_case("pacifico") { "DejaVu Sans" } else { params.title_font.as_str() };
        let wpx = renderer.width(font::FontKind::Sans, fam, t, tsize);
        content_w = content_w.max(wpx / s);
    }
    let window_w = (32.0 + content_w).max(354.0);
    let header_extra = if params.mac { 24.0 } else if params.title.is_some() { 14.0 } else { 0.0 };
    let crumbs_extra = if breadcrumb_path.is_some() { 15.0 } else { 0.0 };
    let window_h = displayed_count as f32 * line_height + 30.0 + header_extra + crumbs_extra;
    let extra_watermark = if params.margin_y >= 82.0 { 72.0 } else { 0.0 };
    let logical_w = window_w + 2.0 * params.margin_x;
    let logical_h = window_h + 2.0 * params.margin_y + extra_watermark;
    let mut img = make_canvas(logical_w, logical_h, params.scale);
    draw_background(&mut img, &params.background, logical_w, logical_h, s);
    let wx = params.margin_x * s; let wy = params.margin_y * s;
    let ww = window_w * s; let wh = window_h * s;
    draw_shadow(&mut img, wx, wy, ww, wh, params.radius * s, params.shadow_radius * s, &params.shadow_color_str);
    // window
    let win_color: Color = (40, 42, 54, 255);
    img.fill_rounded_rect(wx, wy, ww, wh, params.radius * s, win_color);
    // highlights
    let row_top = wy + (14.0 + header_extra + crumbs_extra) * s;
    // helper to test entry membership
    let entry_hits = |e: &HighlightEntry, disp_idx: usize| -> bool {
        // disp_idx 0-based; original line (1-based) for absolute entries is range_start+disp_idx if within selection etc
        if relative_highlight {
            let disp1 = disp_idx + 1;
            disp1 >= e.start && disp1 <= e.end
        } else {
            // original line number of this displayed line
            let orig = if selected_indices.is_empty() { return false; } else { selected_indices[disp_idx] + 1 };
            orig >= e.start && orig <= e.end
        }
    };
    // highlight_range entry
    if let Some(hr) = highlight_range_opt {
        let _ = hr;
        if let Some(e) = entries.first() {
            let col = parse_color(&e.color_str);
            for idx in 0..displayed_count { if entry_hits(e, idx) { img.fill_rect(wx, row_top + idx as f32 * line_height * s, ww, line_height * s, col); } }
        }
    }
    // delete
    {
        let col_str = delete_color;
        if !delete_nums.is_empty() {
            let col = parse_color(col_str);
            for &n in &delete_nums {
                let e = HighlightEntry { start: n, end: n, color_str: col_str.to_string(), is_raw: false };
                for idx in 0..displayed_count { if entry_hits(&e, idx) { img.fill_rect(wx, row_top + idx as f32 * line_height * s, ww, line_height * s, col); } }
            }
        }
    }
    // add
    {
        if !add_nums.is_empty() {
            let col = parse_color(add_color);
            for &n in &add_nums {
                let e = HighlightEntry { start: n, end: n, color_str: add_color.to_string(), is_raw: false };
                for idx in 0..displayed_count { if entry_hits(&e, idx) { img.fill_rect(wx, row_top + idx as f32 * line_height * s, ww, line_height * s, col); } }
            }
        }
    }
    // raw
    for e in &raw_entries {
        match e {
            RawHighlight::Single(n, c) => {
                let col = parse_color(c);
                if *n >= 1 && *n <= displayed_count {
                    img.fill_rect(wx, row_top + (*n - 1) as f32 * line_height * s, ww, line_height * s, col);
                }
            }
            RawHighlight::Range(a,b,c) => {
                let col = parse_color(c);
                let lo = (*a).min(*b); let hi = (*a).max(*b);
                for n in lo..=hi { if n >= 1 && n <= displayed_count { img.fill_rect(wx, row_top + (n-1) as f32 * line_height * s, ww, line_height * s, col); } }
            }
        }
    }
    // border (always drawn with width scaled 1)
    {
        let bcol = parse_color(&params.border_color_str);
        img.stroke_rounded_rect(wx + 0.5*s, wy + 0.5*s, ww - 1.0*s, wh - 1.0*s, params.radius * s, 1.0 * s, bcol);
    }
    // header: mac dots and title
    if params.mac {
        let dot_colors: [Color;3] = [(255,94,87,255),(255,186,46,255),(43,200,65,255)];
        let cy = wy + 22.0 * s;
        for i in 0..3 {
            let cx = wx + (22.0 + 16.0 * i as f32) * s;
            // circle
            let r = 6.0 * s;
            let x0 = (cx - r).floor() as i32; let x1 = (cx + r).ceil() as i32;
            let y0 = (cy - r).floor() as i32; let y1 = (cy + r).ceil() as i32;
            for yy in y0..y1 { for xx in x0..x1 {
                let dx = xx as f32 + 0.5 - cx; let dy = yy as f32 + 0.5 - cy;
                let d = (dx*dx+dy*dy).sqrt();
                let cov = (r - d + 0.5).clamp(0.0,1.0);
                if cov > 0.0 { let a = (dot_colors[i].3 as f32 * cov).round() as u8; img.set_blend(xx, yy, (dot_colors[i].0, dot_colors[i].1, dot_colors[i].2, a)); }
            }}
        }
    }
    if let Some(title) = &params.title {
        let tcol = parse_color(&params.title_color_str);
        let tsize = 11.5 * s;
        let fam = if params.title_font.trim().eq_ignore_ascii_case("pacifico") { "DejaVu Sans" } else { params.title_font.as_str() };
        let tw = renderer.width(font::FontKind::Sans, fam, title, tsize);
        let tx = wx + (ww - tw) / 2.0;
        let baseline = wy + 22.0 * s;
        renderer.draw(&mut img, font::FontKind::Sans, fam, title, tx, baseline, tsize, tcol);
    }
    // breadcrumbs
    if let Some(bp) = &breadcrumb_path {
        let bcol = parse_color(&params.breadcrumbs_color_str);
        let bc_size = 13.3 * s;
        let btext = bp.replace('/', &params.breadcrumbs_separator);
        let btop = 14.0 + header_extra;
        let baseline = wy + (btop + 14.0 + 0.0) * s + crumbs_extra * s - 15.0 * s; // simplify: breadcrumb line top is header region
        // breadcrumb line top is (14 + header_extra) logical, so its baseline is that top + 14
        let baseline = wy + (14.0 + header_extra + 14.0) * s;
        let _ = baseline;
        let _ = btop;
        let baseline2 = wy + (14.0 + header_extra + 14.0) * s;
        renderer.draw(&mut img, font::FontKind::Mono, &params.code_font, &btext, wx + 16.0*s, baseline2, bc_size, bcol);
    }
    // line numbers and code
    let start_num = params.start_line_number.map(|v| v as usize).unwrap_or(range_start);
    let mut highlighter = syntax::Highlighter::new(lang);
    for idx in 0..displayed_count {
        let line = &lines[idx];
        let baseline = row_top + (idx as f32 * line_height + 13.0) * s;
        let code_x = wx + (16.0 + gutter_logical) * s;
        if params.has_line_number {
            let ncol = parse_color(&params.line_number_color_str);
            let num = format!("{}", start_num + idx);
            renderer.draw(&mut img, font::FontKind::Mono, &params.code_font, &num, wx + 16.0*s, baseline, code_size, ncol);
        }
        let segs = highlighter.highlight_line(line);
        let mut cx = code_x;
        for (text, col) in segs {
            renderer.draw(&mut img, font::FontKind::Mono, &params.code_font, &text, cx, baseline, code_size, col);
            cx += renderer.width(font::FontKind::Mono, &params.code_font, &text, code_size);
        }
    }
    // watermark
    if params.margin_y >= 82.0 {
        let wmcol = parse_color(&params.watermark_color_str);
        if !params.watermark_content.is_empty() {
            let wmsize = 36.0 * s;
            let tw = renderer.width(font::FontKind::Serif, &params.watermark_font, &params.watermark_content, wmsize);
            let tx = (img.width as f32 - tw) / 2.0;
            let baseline = wy + wh + 78.0 * s;
            renderer.draw(&mut img, font::FontKind::Serif, &params.watermark_font, &params.watermark_content, tx, baseline, wmsize, wmcol);
        } else {
            // still parse colour above (mirrors original path when watermark is rendered)
            let _ = wmcol;
        }
    }
    Ok(img)
}

fn render_execution(params: &RenderParams, commands: &[String], skip: bool) -> Result<Image, String> {
    // execution already happened in caller if not skip? Caller handles running and passes outputs? 
    // This function runs commands itself for simplicity (called after scale/theme checks? see caller plan)
    // To keep ordering (commands executed during content creation), the caller supplies rendered lines.
    let _ = (commands, skip);
    unreachable!()
}

struct ExecLine { text: String, is_command: bool }

fn render_execution_lines(params: &RenderParams, lines: &[ExecLine]) -> Result<Image, String> {
    if params.scale < 1 { return Err("The scale factor must be greater than 1 ".to_string()); }
    if params.theme != "candy" { return Err(format!("Cannot find {} theme", params.theme)); }
    let s = params.scale as f32;
    let line_height = 20.0f32;
    let code_size = 12.2 * s;
    let mut renderer = font::TextRenderer::new();
    let mut content_w = 0.0f32;
    for l in lines {
        let wpx = renderer.width(font::FontKind::Mono, &params.code_font, &l.text, code_size);
        content_w = content_w.max(wpx / s);
    }
    if let Some(t) = &params.title {
        let tsize = 11.5*s;
        let fam = if params.title_font.trim().eq_ignore_ascii_case("pacifico") { "DejaVu Sans" } else { params.title_font.as_str() };
        content_w = content_w.max(renderer.width(font::FontKind::Sans, fam, t, tsize)/s);
    }
    let window_w = (32.0 + content_w).max(354.0);
    let header_extra = if params.mac { 24.0 } else if params.title.is_some() { 14.0 } else { 0.0 };
    let window_h = lines.len() as f32 * line_height + 30.0 + header_extra;
    // adjust: window_h should be lines*20 + 54 when mac (i.e. 30+24), matches helper above
    let extra_watermark = if params.margin_y >= 82.0 { 72.0 } else { 0.0 };
    let logical_w = window_w + 2.0*params.margin_x;
    let logical_h = window_h + 2.0*params.margin_y + extra_watermark;
    let mut img = make_canvas(logical_w, logical_h, params.scale);
    draw_background(&mut img, &params.background, logical_w, logical_h, s);
    let wx = params.margin_x*s; let wy = params.margin_y*s; let ww = window_w*s; let wh = window_h*s;
    draw_shadow(&mut img, wx, wy, ww, wh, params.radius*s, params.shadow_radius*s, &params.shadow_color_str);
    img.fill_rounded_rect(wx, wy, ww, wh, params.radius*s, (40,42,54,255));
    {
        let bcol = parse_color(&params.border_color_str);
        img.stroke_rounded_rect(wx+0.5*s, wy+0.5*s, ww-1.0*s, wh-1.0*s, params.radius*s, 1.0*s, bcol);
    }
    if params.mac {
        let dot_colors: [Color;3] = [(255,94,87,255),(255,186,46,255),(43,200,65,255)];
        let cy = wy + 22.0*s;
        for i in 0..3 {
            let cx = wx + (22.0 + 16.0*i as f32)*s; let r=6.0*s;
            for yy in (cy-r).floor() as i32..(cy+r).ceil() as i32 { for xx in (cx-r).floor() as i32..(cx+r).ceil() as i32 {
                let dx = xx as f32+0.5-cx; let dy = yy as f32+0.5-cy; let d=(dx*dx+dy*dy).sqrt(); let cov=(r-d+0.5).clamp(0.0,1.0);
                if cov>0.0 { let a=(dot_colors[i].3 as f32*cov).round() as u8; img.set_blend(xx,yy,(dot_colors[i].0,dot_colors[i].1,dot_colors[i].2,a)); }
            }}
        }
    }
    if let Some(title) = &params.title {
        let tcol = parse_color(&params.title_color_str);
        let tsize=11.5*s; let fam = if params.title_font.trim().eq_ignore_ascii_case("pacifico") { "DejaVu Sans" } else { params.title_font.as_str() };
        let tw = renderer.width(font::FontKind::Sans, fam, title, tsize);
        renderer.draw(&mut img, font::FontKind::Sans, fam, title, wx+(ww-tw)/2.0, wy+22.0*s, tsize, tcol);
    }
    let row_top = wy + (14.0 + header_extra)*s;
    for (idx, l) in lines.iter().enumerate() {
        let baseline = row_top + (idx as f32 * line_height + 13.0)*s;
        let code_x = wx + 16.0*s;
        if l.is_command {
            // text is "\u{276F} {cmd}"
            // split prompt and command
            // command text after the first space
            if let Some(space_idx) = l.text.find(' ') {
                let (prompt, rest) = l.text.split_at(space_idx);
                let cmd = &rest[1..];
                // prompt
                renderer.draw(&mut img, font::FontKind::Mono, &params.code_font, prompt, code_x, baseline, code_size, (247,143,179,255));
                let prompt_w = renderer.width(font::FontKind::Mono, &params.code_font, "❯ ", code_size);
                // first word green, rest white
                let mut cx = code_x + prompt_w;
                if let Some(sp) = cmd.find(' ') {
                    let first = &cmd[..sp];
                    renderer.draw(&mut img, font::FontKind::Mono, &params.code_font, first, cx, baseline, code_size, (152,195,121,255));
                    cx += renderer.width(font::FontKind::Mono, &params.code_font, first, code_size);
                    let remainder = &cmd[sp..];
                    renderer.draw(&mut img, font::FontKind::Mono, &params.code_font, remainder, cx, baseline, code_size, (255,255,255,255));
                } else {
                    renderer.draw(&mut img, font::FontKind::Mono, &params.code_font, cmd, cx, baseline, code_size, (152,195,121,255));
                }
            } else {
                renderer.draw(&mut img, font::FontKind::Mono, &params.code_font, &l.text, code_x, baseline, code_size, (255,255,255,255));
            }
        } else {
            renderer.draw(&mut img, font::FontKind::Mono, &params.code_font, &l.text, code_x, baseline, code_size, (151,158,171,255));
        }
    }
    if params.margin_y >= 82.0 {
        let wmcol = parse_color(&params.watermark_color_str);
        if !params.watermark_content.is_empty() {
            let wmsize=36.0*s; let tw=renderer.width(font::FontKind::Serif, &params.watermark_font, &params.watermark_content, wmsize);
            renderer.draw(&mut img, font::FontKind::Serif, &params.watermark_font, &params.watermark_content, (img.width as f32-tw)/2.0, wy+wh+78.0*s, wmsize, wmcol);
        }
    }
    Ok(img)
}

fn render_image_snapshot(params: &RenderParams, image_bytes: &[u8]) -> Result<Image, String> {
    if params.scale < 1 { return Err("The scale factor must be greater than 1 ".to_string()); }
    if params.theme != "candy" { return Err(format!("Cannot find {} theme", params.theme)); }
    let src = image::decode_png(image_bytes).map_err(|e| e.0)?;
    let s = params.scale as f32;
    // logical window size is the image dimensions
    let window_w = src.width as f32;
    let window_h = src.height as f32;
    let extra_watermark = if params.margin_y >= 82.0 { 72.0 } else { 0.0 };
    let logical_w = window_w + 2.0*params.margin_x;
    let logical_h = window_h + 2.0*params.margin_y + extra_watermark;
    let mut img = make_canvas(logical_w, logical_h, params.scale);
    draw_background(&mut img, &params.background, logical_w, logical_h, s);
    let wx = params.margin_x*s; let wy = params.margin_y*s; let ww = window_w*s; let wh = window_h*s;
    draw_shadow(&mut img, wx, wy, ww, wh, params.radius*s, params.shadow_radius*s, &params.shadow_color_str);
    // draw image scaled
    let dw = (src.width as f32 * s) as u32; let dh = (src.height as f32 * s) as u32;
    img.draw_image_scaled(&src, wx, wy, dw, dh);
    // watermark
    if params.margin_y >= 82.0 {
        let wmcol = parse_color(&params.watermark_color_str);
        if !params.watermark_content.is_empty() {
            let mut renderer = font::TextRenderer::new();
            let wmsize=36.0*s; let tw=renderer.width(font::FontKind::Serif, &params.watermark_font, &params.watermark_content, wmsize);
            renderer.draw(&mut img, font::FontKind::Serif, &params.watermark_font, &params.watermark_content, (img.width as f32-tw)/2.0, wy+wh+78.0*s, wmsize, wmcol);
        }
    }
    Ok(img)
}

// ---------- output helpers ----------
fn local_datetime_string() -> String {
    // UTC civil conversion from unix time
    let secs = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map(|d| d.as_secs() as i64).unwrap_or(0);
    let days = secs.div_euclid(86400);
    let tod = secs.rem_euclid(86400);
    let h = tod/3600; let m=(tod%3600)/60; let sec=tod%60;
    // civil from days (Howard Hinnant)
    let z = days + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = z - era*146097;
    let yoe = (doe - doe/1460 + doe/36524 - doe/146096)/365;
    let y = yoe + era*400;
    let doy = doe - (365*yoe + yoe/4 - yoe/100);
    let mp = (5*doy + 2)/153;
    let d = doy - (153*mp+2)/5 + 1;
    let month = if mp < 10 { mp+3 } else { mp-9 };
    let year = if month <= 2 { y+1 } else { y };
    format!("{:04}-{:02}-{:02}_at_{:02}:{:02}:{:02}", year, month, d, h, m, sec)
}

fn run(matches: &clap::ArgMatches) -> Result<(), String> {
    // config
    let cli_config = matches.get_one::<String>("config");
    let config = load_config(cli_config)?;
    if config.snapshot_config.background.is_none() {
        return Err("`background` must be initialized".to_string());
    }
    let silent = matches.get_flag("silent");
    let output = matches.get_one::<String>("output").unwrap().clone();
    let snapshot_type = matches.get_one::<String>("r#type").map(|s| s.as_str()).unwrap_or("image");
    // determine content (precedence: execute, from_image, from_file, from_code, from_clipboard)
    let execute_vals: Option<Vec<String>> = matches.get_many::<String>("execute").map(|v| v.cloned().collect());
    let from_image_present = matches.contains_id("from_image") && matches.get_occurrences::<String>("from_image").map(|mut o| o.next().is_some()).unwrap_or(false) || matches.try_get_count_of("from_image");
    // Use contains_id robustly:
    let from_image_present = {
        // clap: if arg was present on command line, get_occurrences returns Some even if no values? We'll check indices via value source
        matches.value_source("from_image") == Some(clap::parser::ValueSource::CommandLine)
    };
    let from_code_present = matches.value_source("from_code") == Some(clap::parser::ValueSource::CommandLine);
    let content: Content;
    let mut exec_lines: Vec<ExecLine> = Vec::new();
    if let Some(cmds) = execute_vals {
        // run commands now (as original does during content creation)
        let skip = matches.get_flag("skip");
        for cmd in &cmds {
            exec_lines.push(ExecLine { text: format!("❯ {}", cmd), is_command: true });
            if skip {
                exec_lines.push(ExecLine { text: String::new(), is_command: false });
            } else {
                let out = std::process::Command::new("sh").arg("-c").arg(cmd).stdin(std::process::Stdio::null()).output();
                match out {
                    Ok(o) => {
                        let stdout = String::from_utf8_lossy(&o.stdout).to_string();
                        if stdout.is_empty() {
                            exec_lines.push(ExecLine { text: String::new(), is_command: false });
                        } else {
                            for line in stdout.lines() { exec_lines.push(ExecLine { text: line.replace('\t', "  "), is_command: false }); }
                        }
                    }
                    Err(e) => {
                        panic_emulate("cli/src/code.rs:62:14", &format!("failed to execute process: {:?}", e));
                    }
                }
            }
        }
        content = Content::Execution { commands: cmds };
    } else if from_image_present {
        let bytes = if let Some(v) = matches.get_one::<String>("from_image") {
            v.clone().into_bytes()
        } else {
            let mut buf = Vec::new();
            std::io::stdin().read_to_end(&mut buf).map_err(|e| e.to_string())?;
            buf
        };
        content = Content::ImageBytes(bytes);
    } else if let Some(file) = matches.get_one::<String>("from_file") {
        let p = Path::new(file);
        if p.exists() && !p.is_file() {
            return Err("The file path is not a file".to_string());
        }
        let code = std::fs::read_to_string(p).map_err(|e| e.to_string())?;
        content = Content::Raw { code, source_file: Some(file.clone()) };
    } else if from_code_present {
        if let Some(v) = matches.get_one::<String>("from_code") {
            content = Content::Raw { code: v.clone(), source_file: None };
        } else {
            let mut buf = Vec::new();
            std::io::stdin().read_to_end(&mut buf).map_err(|e| e.to_string())?;
            let code = String::from_utf8(buf).map_err(|e| e.to_string())?;
            content = Content::Raw { code, source_file: None };
        }
    } else if matches.get_flag("from_clipboard") {
        let text = try_clipboard_get_text()?;
        content = Content::Raw { code: text, source_file: None };
    } else {
        return Err("No code snippet provided".to_string());
    }

    // Build render params from config + CLI
    let snapshot = &config.snapshot_config;
    let window_cfg: Window = snapshot.window.clone().unwrap_or_default();
    let code_cfg: CodeConfig = snapshot.code_config.clone().unwrap_or_default();
    let breadcrumbs_cfg: Breadcrumbs = code_cfg.breadcrumbs.clone().unwrap_or_default();
    let watermark_cfg: Watermark = snapshot.watermark.clone().unwrap_or_default();
    let params = RenderParams {
        scale: *matches.get_one::<u8>("scale_factor").unwrap_or(&3),
        theme: matches.get_one::<String>("code_theme").cloned().or_else(|| snapshot.theme.clone()).unwrap_or_else(|| "candy".to_string()),
        mac: matches.get_one::<bool>("mac_window_bar").copied().unwrap_or(window_cfg.mac_window_bar),
        title: matches.get_one::<String>("title").cloned(),
        title_color_str: matches.get_one::<String>("title_color").cloned().unwrap_or_else(|| window_cfg.title_config.color.clone()),
        title_font: matches.get_one::<String>("title_font_family").cloned().unwrap_or_else(|| window_cfg.title_config.font_family.clone()),
        shadow_radius: matches.get_one::<f32>("shadow_radius").copied().unwrap_or(window_cfg.shadow.radius),
        shadow_color_str: matches.get_one::<String>("shadow_color").cloned().unwrap_or_else(|| window_cfg.shadow.color.clone()),
        margin_x: matches.get_one::<f32>("margin_x").copied().unwrap_or(window_cfg.margin.x),
        margin_y: matches.get_one::<f32>("margin_y").copied().unwrap_or(window_cfg.margin.y),
        border_color_str: matches.get_one::<String>("border_color").cloned().unwrap_or_else(|| "#ffffff30".to_string()),
        radius: window_cfg.radius,
        code_font: matches.get_one::<String>("code_font_family").cloned().unwrap_or_else(|| code_cfg.font_family.clone()),
        breadcrumbs_enable: *matches.get_one::<bool>("has_breadcrumbs").unwrap_or(&false),
        breadcrumbs_separator: matches.get_one::<String>("breadcrumbs_separator").cloned().unwrap_or_else(|| breadcrumbs_cfg.separator.clone()),
        breadcrumbs_color_str: matches.get_one::<String>("breadcrumbs_color").cloned().unwrap_or_else(|| breadcrumbs_cfg.color.clone()),
        has_line_number: matches.get_flag("has_line_number"),
        start_line_number: matches.get_one::<u32>("start_line_number").copied(),
        line_number_color_str: matches.get_one::<String>("line_number_color").cloned().unwrap_or_else(|| "#495162".to_string()),
        background: snapshot.background.clone().unwrap(),
        watermark_content: matches.get_one::<String>("watermark").cloned().unwrap_or_else(|| watermark_cfg.content.clone()),
        watermark_font: matches.get_one::<String>("watermark_font_family").cloned().unwrap_or_else(|| watermark_cfg.font_family.clone()),
        watermark_color_str: matches.get_one::<String>("watermark_color").cloned().unwrap_or_else(|| watermark_cfg.color.clone()),
    };

    // ASCII branch
    if snapshot_type == "ascii" {
        // For Raw, validations etc are performed inside render_code path? We mirror:
        // Perform raw validations (range/highlights/scale) without rendering by invoking a validation-only pass.
        // Simplest: if Content is Raw, call render_code validations up to scale stage would be costly but ok.
        // We instead run equivalent checks here:
        match &content {
            Content::Raw { code, source_file } => {
                // run checks via dry rendering to same size? Use render_code but ignore result when output is not clipboard? 
                // Original still produces warning without generating an image, but errors come from highlight parsing/validation and scale.
                // We'll perform checks:
                check_raw_validations(matches, code)?;
                if output != "clipboard" {
                    log_warn("ASCII snapshot only supports copying to clipboard");
                    if config.print_eggs { print_eggs(); }
                    return Ok(());
                } else {
                    // generate ascii (plain text with line numbers?) and try clipboard
                    let ascii = build_ascii(code, matches);
                    try_clipboard_set_text(&ascii)?;
                    if !silent { log_success(&format!("Snapshot saved to {} successful!", output)); }
                    if config.print_eggs { print_eggs(); }
                    return Ok(());
                }
            }
            Content::Execution { .. } | Content::ImageBytes(_) => {
                // scale check still occurs
                if params.scale < 1 { return Err("The scale factor must be greater than 1 ".to_string()); }
                if output != "clipboard" {
                    log_warn("ASCII snapshot only supports copying to clipboard");
                    if config.print_eggs { print_eggs(); }
                    return Ok(());
                } else {
                    return Err("The code content is not raw".to_string());
                }
            }
        }
    }

    // Image branch
    let img: Image = match &content {
        Content::Raw { code, source_file } => {
            let delete_vals: Vec<String> = matches.get_many::<String>("delete_line").map(|v| v.cloned().collect()).unwrap_or_default();
            let add_vals: Vec<String> = matches.get_many::<String>("add_line").map(|v| v.cloned().collect()).unwrap_or_default();
            render_code(
                &params,
                code,
                source_file.as_deref(),
                matches.get_one::<String>("file_path").map(|s| s.as_str()),
                matches.get_one::<String>("language").map(|s| s.as_str()),
                matches.get_one::<String>("range").map(|s| s.as_str()),
                matches.get_one::<String>("highlight_range").map(|s| s.as_str()),
                matches.get_flag("relative_highlight_range"),
                matches.get_one::<String>("highlight_range_color").map(|s| s.as_str()).unwrap_or("#ffffff10"),
                matches.get_one::<String>("raw_highlight_lines").map(|s| s.as_str()),
                &delete_vals,
                matches.get_one::<String>("delete_line_color").map(|s| s.as_str()).unwrap_or("#ff6b6b30"),
                &add_vals,
                matches.get_one::<String>("add_line_color").map(|s| s.as_str()).unwrap_or("#2ecc7130"),
            )?
        }
        Content::Execution { .. } => {
            render_execution_lines(&params, &exec_lines)?
        }
        Content::ImageBytes(bytes) => {
            render_image_snapshot(&params, bytes)?
        }
    };

    // output
    if output == "clipboard" {
        let png = img.to_png();
        try_clipboard_set_image(&png, img.width, img.height)?;
        if !silent { log_success(&format!("Snapshot saved to {} successful!", output)); }
        if config.print_eggs { print_eggs(); }
        return Ok(());
    }
    // determine extension from output string after last '.'
    let ext = output.rsplit('.').next().unwrap_or("");
    let png_bytes = img.to_png();
    let content_bytes: Vec<u8> = match ext {
        "png" => png_bytes.clone(),
        "svg" => {
            let b64 = base64::Engine::encode(&base64::engine::general_purpose::STANDARD, &png_bytes);
            format!("<svg xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"><image href=\"data:image/png;base64,{}\"/></svg>", b64).into_bytes()
        }
        "html" => {
            let b64 = base64::Engine::encode(&base64::engine::general_purpose::STANDARD, &png_bytes);
            format!("<img src=\"data:image/png;base64,{}\" />", b64).into_bytes()
        }
        _ => return Err("Unsupported output format".to_string()),
    };
    // if output path is a directory, generate temp file inside it
    let out_path = Path::new(&output);
    let write_path: PathBuf = if out_path.is_dir() {
        out_path.join(format!("CodeSnap_{}", local_datetime_string()))
    } else {
        out_path.to_path_buf()
    };
    std::fs::write(&write_path, &content_bytes).map_err(|e| e.to_string())?;
    if !silent { log_success(&format!("Snapshot saved to {} successful!", output)); }
    if config.print_eggs { print_eggs(); }
    Ok(())
}

fn check_raw_validations(matches: &clap::ArgMatches, code: &str) -> Result<(), String> {
    // replicate validations performed in image path for Raw content (without theme/language/render)
    let total = split_code_lines(code).len();
    if let Some(r) = matches.get_one::<String>("range") {
        let _ = parse_range(r, total)?;
    }
    if let Some(raw) = matches.get_one::<String>("raw_highlight_lines") {
        let entries = parse_raw_highlights(raw)?;
        for e in &entries { match e { RawHighlight::Single(_,c) => { parse_color(c); }, RawHighlight::Range(_,_,c) => { parse_color(c); } } }
    }
    // need range_start/end for validation
    let (mut rs, mut re) = (1usize, total);
    if let Some(r) = matches.get_one::<String>("range") {
        let (a,b) = parse_range(r, total)?;
        rs = a.min(b); re = a.max(b);
    }
    let selected_count = if matches.get_one::<String>("range").is_some() { re - rs + 1 } else { total };
    let display_count = selected_count.min(total);
    let mut vals: Vec<(usize,usize)> = Vec::new();
    if let Some(hr) = matches.get_one::<String>("highlight_range") {
        let (mut a, mut b) = parse_range(hr, total)?;
        if a > b { std::mem::swap(&mut a, &mut b); }
        vals.push((a,b));
    }
    let delete_vals: Vec<String> = matches.get_many::<String>("delete_line").map(|v| v.cloned().collect()).unwrap_or_default();
    for d in &delete_vals { vals.push((parse_usize(d)?, parse_usize(d)?)); }
    let add_vals: Vec<String> = matches.get_many::<String>("add_line").map(|v| v.cloned().collect()).unwrap_or_default();
    for a in &add_vals { let n = parse_usize(a)?; vals.push((n,n)); }
    let relative = matches.get_flag("relative_highlight_range");
    for (a,b) in &vals {
        if relative {
            if *b > display_count {
                return Err(format!("The highlight end range should be less than or equal to {}", re.wrapping_sub(rs)));
            }
        } else {
            if *a < rs { return Err(format!("The highlight start range should be greater than or equal to {}", rs)); }
            if *b > re { return Err(format!("The highlight end range should be less than or equal to {}", re)); }
        }
    }
    let scale = *matches.get_one::<u8>("scale_factor").unwrap_or(&3);
    if scale < 1 { return Err("The scale factor must be greater than 1 ".to_string()); }
    Ok(())
}

fn build_ascii(code: &str, matches: &clap::ArgMatches) -> String {
    let _ = matches;
    // simple ascii rendering: code lines as-is
    split_code_lines(code).join("\n")
}

fn main() {
    let matches = build_cli().get_matches();
    match run(&matches) {
        Ok(()) => std::process::exit(0),
        Err(msg) => { log_error(&msg); std::process::exit(1); }
    }
}
RUST
"}

